/* Spanish translation of the CompTIA A+ Core 2 practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("a-plus-core2", {
  "ap1": ["Una pequeña empresa quiere unir sus nuevas laptops a un dominio de Active Directory y cifrarlas con BitLocker. ¿Cuál es la edición de Windows 11 más básica que admite ambas cosas?", ["Home", "Pro", "Enterprise", "Education"], "Windows 11 Pro admite la unión a dominio y BitLocker. Home no admite ninguna de las dos; Enterprise y Education también las admiten, pero son ediciones por volumen de nivel superior.", ["Windows 11 Home no puede unirse a un dominio de Active Directory y no tiene la administración completa de BitLocker (solo ofrece el cifrado de dispositivo básico en algunos equipos).", null, "Enterprise admite ambas funciones, pero es una edición con licencia por volumen de nivel superior, así que no es la edición más básica que cumple.", "Education admite ambas funciones, pero es una edición académica con licencia por volumen por encima de Pro, así que no es la más básica que cumple."]],
  "ap2": ["Un técnico debe copiar un video de 6 GB a una memoria USB que debe funcionar tanto en Windows como en macOS. ¿Qué sistema de archivos debe usar la memoria?", ["FAT32", "NTFS", "ext4", "exFAT"], "exFAT permite lectura y escritura en ambos sistemas operativos y no tiene el límite de 4 GB por archivo. FAT32 no puede almacenar archivos de más de 4 GB, y macOS monta NTFS como solo lectura de forma predeterminada.", ["FAT32 funciona en Windows y macOS, pero limita cada archivo a 4 GB, así que un video de 6 GB no cabe.", "NTFS maneja archivos grandes, pero macOS monta los volúmenes NTFS como solo lectura de forma predeterminada, así que la Mac no podría escribir en la memoria.", "ext4 es un sistema de archivos de Linux que ni Windows ni macOS pueden leer o escribir de forma nativa.", null]],
  "ap3": ["Un nuevo disco de 4 TB debe configurarse como un solo volumen en una PC con UEFI. ¿Qué estilo de partición debe usarse?", ["GPT", "MBR", "Extendida", "Volumen distribuido dinámico"], "GPT admite volúmenes mucho mayores de 2 TB y es necesario para el arranque UEFI. MBR llega como máximo a 2 TB.", [null, "MBR solo puede direccionar discos de hasta 2 TB y no se usa para el arranque UEFI nativo, así que un solo volumen de 4 TB desperdiciaría espacio.", "Una partición extendida es un recurso de MBR para crear más de cuatro particiones; no elimina el límite de 2 TB de MBR.", "Un volumen distribuido dinámico une espacio de varios discos en un solo volumen; no es un estilo de partición y no es necesario para un solo disco."]],
  "ap4": ["¿Qué comando repara los archivos protegidos del sistema de Windows que están dañados reemplazándolos con copias en caché?", ["chkdsk /r", "gpupdate /force", "sfc /scannow", "diskpart"], "El Comprobador de archivos de sistema (sfc /scannow) verifica y reemplaza los archivos protegidos del sistema. chkdsk repara errores del sistema de archivos y sectores dañados, no archivos del sistema.", ["chkdsk /r revisa el sistema de archivos y localiza sectores dañados, pero no verifica ni restaura los archivos protegidos de Windows.", "gpupdate /force vuelve a aplicar la configuración de Group Policy; no tiene nada que ver con reparar archivos del sistema.", null, "diskpart administra discos, particiones y volúmenes; no puede revisar ni reemplazar archivos del sistema dañados."]],
  "ap5": ["sfc /scannow informa que encontró archivos dañados, pero no pudo reparar algunos. ¿Qué debe ejecutar el técnico a continuación?", ["DISM /Online /Cleanup-Image /RestoreHealth", "gpresult /r", "format C: /q", "netstat -an"], "DISM repara el almacén de componentes que sfc usa como fuente; cuando termine, hay que volver a ejecutar sfc.", [null, "gpresult /r solo informa qué configuraciones de Group Policy se aplican al usuario y al equipo; no repara nada.", "Formatear C: borra todo el sistema operativo y los datos del usuario, un paso drástico cuando DISM puede reparar el almacén de componentes.", "netstat -an enumera las conexiones de red y los puertos en escucha; no interviene en la reparación de archivos de Windows."]],
  "ap6": ["Un administrador cambió una configuración de Group Policy y quiere que la PC de un usuario la aplique de inmediato en lugar de esperar. ¿Qué comando debe ejecutar el usuario?", ["gpresult /r", "gpupdate /force", "gpresult /h report.html", "whoami /groups"], "gpupdate /force vuelve a aplicar ahora todas las directivas de equipo y de usuario. gpresult /r solo informa qué directivas están aplicadas.", ["gpresult /r muestra el conjunto resultante de directivas aplicadas actualmente, pero no inicia una nueva actualización de directivas.", null, "gpresult /h genera un informe HTML de las directivas aplicadas; es una herramienta de informes y no aplica nada.", "whoami /groups enumera los grupos de seguridad del token del usuario; no actualiza Group Policy."]],
  "ap7": ["Un técnico necesita copiar un árbol de carpetas grande a un servidor de archivos, conservar los permisos y reanudar si la red se cae. ¿Qué comando es el MÁS adecuado?", ["copy", "xcopy", "diskpart", "robocopy"], "Robocopy maneja árboles grandes, puede copiar permisos NTFS (/COPYALL) y reintenta o reanuda en modo reiniciable. copy y xcopy no tienen estas funciones.", ["copy maneja archivos individuales, no árboles de carpetas completos, y no puede conservar permisos NTFS ni reanudar después de una caída de la red.", "xcopy puede copiar árboles de carpetas, pero no tiene el modo reiniciable de robocopy, los reintentos automáticos ni la copia completa de permisos.", "diskpart administra particiones y volúmenes de disco; no copia archivos en absoluto.", null]],
  "ap8": ["Un usuario quiere una unidad asignada con la letra P: que apunte a \\\\fs01\\projects. ¿Qué comando la crea?", ["net user P: \\\\fs01\\projects", "diskpart assign letter=P", "nslookup P: fs01", "net use P: \\\\fs01\\projects"], "net use asigna una letra de unidad a un recurso compartido de red. net user administra cuentas de usuario, y diskpart asigna letras a volúmenes locales.", ["net user crea y administra cuentas de usuario locales; no puede asignar una letra de unidad a un recurso compartido.", "El comando assign de diskpart da una letra de unidad a un volumen local, no a la ruta de un recurso compartido de red.", "nslookup consulta el DNS para resolver nombres; no crea asignaciones de unidades.", null]],
  "ap9": ["Un técnico quiere ver qué programas y servicios se ejecutan en cada inicio y programar una tarea para ejecutar un script cada noche. ¿Qué dos herramientas debe usar?", ["La pestaña Aplicaciones de arranque del Administrador de tareas y el Programador de tareas", "Administración de discos y Administrador de dispositivos", "Administrador de certificados y Visor de eventos", "Editor del Registro y Liberador de espacio en disco"], "El Administrador de tareas muestra el impacto en el inicio y permite deshabilitar aplicaciones de arranque; el Programador de tareas ejecuta programas según una programación.", [null, "Administración de discos maneja volúmenes y el Administrador de dispositivos maneja drivers de hardware; ninguno administra aplicaciones de arranque ni tareas programadas.", "El Administrador de certificados administra certificados y el Visor de eventos muestra registros; ninguno controla los programas de inicio ni la programación.", "El Editor del Registro puede mostrar las claves Run, pero es riesgoso e indirecto, y el Liberador de espacio en disco solo elimina archivos temporales; ninguno programa tareas."]],
  "ap10": ["Un driver de impresora sigue causando errores. ¿Qué herramienta permite al técnico revertir el driver a la versión anterior?", ["Monitor de rendimiento", "Usuarios y grupos locales", "Administrador de dispositivos", "Información del sistema"], "La pestaña Controlador del Administrador de dispositivos ofrece Revertir al controlador anterior. Información del sistema solo informa detalles del hardware y los drivers.", ["El Monitor de rendimiento registra contadores de rendimiento a lo largo del tiempo; no puede cambiar ni revertir drivers.", "Usuarios y grupos locales administra cuentas y membresías de grupos, no drivers de dispositivos.", null, "Información del sistema muestra detalles de hardware y drivers en modo solo lectura; no tiene opción para revertir un driver."]],
  "ap11": ["Un técnico necesita un informe completo del hardware de la PC, la versión del BIOS y los drivers cargados sin cambiar nada. ¿Qué herramienta es la MEJOR?", ["msconfig", "diskmgmt.msc", "regedit", "msinfo32"], "Información del sistema (msinfo32) es un informe de solo lectura de los recursos de hardware, los componentes y el entorno de software.", ["msconfig cambia opciones de arranque e inicio; es una herramienta de configuración, no un informe completo de hardware y drivers.", "Administración de discos solo muestra y cambia discos y volúmenes; no informa la versión del BIOS ni los drivers.", "El Editor del Registro edita el registro directamente, lo que implica riesgo de cambios, y no es un informe de inventario legible.", null]],
  "ap12": ["Una laptop está configurada con el perfil de red Pública en una cafetería. ¿Qué cambia esto en comparación con un perfil Privado?", ["La PC recibe una dirección IP estática", "DHCP se deshabilita para el adaptador", "El cliente VPN se conecta automáticamente en cada inicio de sesión", "La detección de redes y el uso compartido de archivos se desactivan"], "El perfil Público oculta la PC de los demás deshabilitando la detección y el uso compartido. No cambia la forma en que se asigna la dirección.", ["Los perfiles de red no controlan el direccionamiento; la PC sigue usando la configuración DHCP o estática que ya tenía.", "El perfil Público no deshabilita DHCP; solo cambia las reglas del firewall, la detección y el uso compartido.", "Conectar automáticamente una VPN es una configuración independiente del cliente VPN, no algo que active el perfil Público.", null]],
  "ap13": ["Un usuario con un hotspot celular limitado se queja de que Windows Update consumió la mayor parte de sus datos. ¿Qué configuración debe habilitarse?", ["Conexión de uso medido", "Hibernar después de 15 minutos de inactividad", "Inicio rápido", "Hibernar"], "Marcar una conexión como de uso medido hace que Windows posponga la mayoría de las descargas de actualizaciones y el uso de datos en segundo plano.", [null, "Hibernar después de un tiempo de inactividad solo ahorra batería; no impide que Windows Update descargue datos.", "El inicio rápido acorta el arranque hibernando parcialmente el kernel; no afecta el uso de datos de las actualizaciones.", "Hibernar es un estado de energía que guarda la RAM en disco; no limita las descargas en segundo plano mientras la PC está encendida."]],
  "ap14": ["Una PC con Windows tiene la IP 192.168.10.25, pero no puede llegar a ningún sitio web por nombre, aunque el ping a 8.8.8.8 funciona. ¿Qué configuración es MÁS probable que esté mal?", ["Máscara de subred", "Gateway predeterminado", "Servidor DNS", "Lista de excepciones del proxy"], "Llegar a una IP de internet demuestra que el enrutamiento y el gateway funcionan; si solo falla por nombre, el problema apunta al DNS.", ["Una máscara de subred incorrecta normalmente impediría comunicarse con el gateway u otros hosts, pero la PC llega sin problema a 8.8.8.8.", "El ping a una IP de internet funciona, lo que demuestra que el gateway predeterminado está funcionando.", null, "Una lista de excepciones del proxy solo afecta qué sitios evitan el proxy; no impediría la resolución de nombres de todos los sitios."]],
  "ap15": ["Un usuario de Mac necesita respaldos automáticos cada hora de sus archivos en un disco externo. ¿Qué función integrada debe configurar el técnico?", ["FileVault", "Time Machine", "Acceso a Llaveros (Keychain Access)", "Spotlight"], "Time Machine respalda automáticamente en un disco externo o de red. FileVault es cifrado de disco completo.", ["FileVault es el cifrado de disco completo de macOS; protege los datos en reposo, pero no hace respaldos.", null, "Acceso a Llaveros almacena contraseñas, claves y certificados; no respalda los archivos del usuario.", "Spotlight es la función de búsqueda de macOS; indexa archivos, pero no los copia a ningún lado."]],
  "ap16": ["Una aplicación en una Mac se congeló y no responde a su propio comando Salir. ¿Cuál es la forma integrada más rápida de cerrarla?", ["Abrir Utilidad de Discos y ejecutar Primeros auxilios", "Abrir Mission Control y deslizar hacia arriba", "Eliminar la aplicación de la carpeta Aplicaciones", "Presionar Command+Option+Esc y usar Forzar salida"], "Forzar salida de aplicaciones termina una aplicación colgada. Mission Control solo organiza ventanas, y eliminar la aplicación no detiene un proceso en ejecución.", ["Primeros auxilios de Utilidad de Discos revisa y repara errores del disco y del sistema de archivos; no termina una aplicación congelada.", "Mission Control solo muestra y organiza las ventanas y escritorios abiertos; no termina un proceso colgado.", "Eliminar el paquete de la aplicación la quita del disco, pero el proceso en ejecución permanece en memoria y sigue congelado.", null]],
  "ap17": ["En un servidor Linux, un archivo de script debe ser ejecutable solo por su propietario. ¿Qué comando lo configura?", ["sudo 700 script.sh", "chown 700 script.sh", "chmod 777 script.sh", "chmod 700 script.sh"], "chmod 700 le da al propietario lectura, escritura y ejecución y quita todos los permisos al grupo y a los demás. chown cambia la propiedad, no los permisos.", ["sudo ejecuta un comando con privilegios de root; '700' no es un comando, así que esto no cambia los permisos del archivo.", "chown cambia el propietario y el grupo de un archivo, no sus bits de permisos, así que no puede hacerlo ejecutable solo por el propietario.", "chmod 777 da lectura, escritura y ejecución al propietario, al grupo y a todos los demás, lo contrario del acceso solo para el propietario.", null]],
  "ap18": ["Un técnico debe instalar un paquete en una estación de trabajo Ubuntu. ¿Qué comando debe usar?", ["sudo dnf install htop", "sudo apt install htop", "chmod +x htop", "ps htop"], "Ubuntu y Debian usan el gestor de paquetes apt, y las instalaciones requieren root, así que se usa sudo apt install. dnf se usa en distribuciones basadas en Red Hat.", ["dnf es el gestor de paquetes de las distribuciones basadas en Red Hat, como Fedora y RHEL, no de Ubuntu.", null, "chmod +x solo marca un archivo existente como ejecutable; no descarga ni instala un paquete.", "ps enumera los procesos en ejecución; no puede instalar software."]],
  "ap19": ["¿Qué archivo de Linux almacena los hashes de las contraseñas de los usuarios?", ["/etc/passwd", "/etc/hosts", "/etc/shadow", "/etc/fstab"], "/etc/shadow contiene los hashes de las contraseñas y solo root puede leerlo. /etc/passwd enumera las cuentas, pero ya no almacena los hashes.", ["/etc/passwd enumera las cuentas de usuario y todos pueden leerlo; en Linux moderno los hashes se movieron de ahí a /etc/shadow.", "/etc/hosts asigna nombres de host a direcciones IP para la resolución local de nombres; no contiene contraseñas.", null, "/etc/fstab define qué sistemas de archivos se montan al arrancar y dónde; no tiene nada que ver con contraseñas."]],
  "ap20": ["Un usuario quiere instalar un programa de diseño 3D en una laptop con Windows 10 de 32 bits y 4 GB de RAM. El fabricante exige un sistema operativo de 64 bits y 16 GB de RAM. ¿Cuál es el MEJOR consejo?", ["Instalarlo de todos modos y luego ampliar el archivo de paginación para compensar la RAM faltante", "Ejecutarlo en modo de compatibilidad", "Instalarlo desde una ISO en lugar de una descarga", "La laptop no cumple los requisitos; actualizar el hardware y el sistema operativo o usar otra PC"], "Una aplicación de 64 bits no puede ejecutarse en un sistema operativo de 32 bits, y una RAM por debajo del mínimo no se corrige con configuraciones. El sistema debe cumplir los requisitos.", ["Un archivo de paginación más grande no reemplaza la RAM física faltante ni puede hacer que un programa de 64 bits funcione en un sistema de 32 bits.", "El modo de compatibilidad imita versiones anteriores de Windows para aplicaciones antiguas; no puede ejecutar código de 64 bits en un sistema de 32 bits ni agregar RAM.", "El medio de instalación no cambia nada; el programa sigue necesitando un sistema operativo de 64 bits y 16 GB de RAM.", null]],
  "ap21": ["TI necesita instalar la misma compilación estándar de Windows en 60 PC de escritorio nuevas que admiten arranque por red. ¿Qué método es el MÁS eficiente?", ["Implementación de imagen mediante PXE", "Una instalación limpia desde DVD en cada PC", "Una actualización in situ en cada PC", "Una instalación de reparación en cada PC"], "El arranque PXE con implementación de imágenes envía una imagen preparada a muchas PC por la red, en lugar de instalar cada una a mano.", [null, "Instalar desde DVD en cada una de las 60 PC es un trabajo manual lento y produce compilaciones inconsistentes.", "Una actualización in situ conserva un sistema operativo existente y su configuración; las PC nuevas necesitan una compilación estándar limpia, y hacer cada una a mano es lento.", "Una instalación de reparación corrige una instalación de Windows existente dañada; no es una forma de implementar una compilación estándar en equipos nuevos."]],
  "ap22": ["Se está actualizando una PC con Windows 10 a Windows 11, pero la verificación de actualización falla. ¿Qué función de hardware faltante es la causa MÁS probable en una PC antigua?", ["Un disco NVMe", "TPM 2.0", "Una GPU dedicada", "Un adaptador Wi-Fi 6"], "Windows 11 requiere TPM 2.0 y UEFI con capacidad de Secure Boot. NVMe, una GPU dedicada y Wi-Fi 6 no son requisitos.", ["Windows 11 funciona en discos SATA o NVMe; solo necesita 64 GB de almacenamiento, no una interfaz de disco específica.", null, "Windows 11 necesita un adaptador gráfico compatible con DirectX 12, lo que cumplen los gráficos integrados; no se requiere una GPU dedicada.", "Wi-Fi 6 no es un requisito de Windows 11; el sistema funciona con adaptadores Wi-Fi más antiguos o con conexión cableada."]],
  "ap23": ["Un nuevo empleado necesita correo, documentos compartidos y videoconferencias desde cualquier dispositivo, con archivos sincronizados en su laptop. ¿Qué debe configurar el técnico PRIMERO?", ["Un cliente de correo local solo con POP3", "Una unidad asignada al servidor de archivos local más una copia local de Office", "Una cuenta de usuario y una licencia en la suite de productividad en la nube de la empresa", "Una VPN hacia un router doméstico"], "Las herramientas de productividad en la nube comienzan con la creación de una cuenta y la asignación de una licencia, y luego la sincronización y configuración de aplicaciones en cada dispositivo.", ["POP3 descarga el correo a un solo dispositivo y no sincroniza entre dispositivos, además de no ofrecer documentos compartidos ni reuniones.", "Una unidad asignada solo funciona en la red de la oficina o por VPN, y no ofrece sincronización en la nube ni reuniones desde cualquier dispositivo.", null, "Una VPN hacia un router doméstico da acceso a esa red doméstica; no proporciona correo, documentos ni reuniones."]],
  "ap24": ["¿Qué configuración de energía de Windows guarda el contenido de la RAM en disco y apaga el equipo por completo, sin consumir batería mientras está apagado?", ["Suspender", "Protector de pantalla", "Inicio rápido", "Hibernar"], "Hibernar escribe la memoria en hiberfil.sys y apaga la PC. Suspender mantiene la RAM alimentada, así que sigue usando algo de batería.", ["Suspender mantiene la RAM alimentada para que la PC se reanude rápido, así que sigue consumiendo algo de batería.", "Un protector de pantalla solo cubre o apaga la pantalla mientras la PC sigue funcionando a plena potencia.", "El inicio rápido guarda la sesión del kernel al apagar para acelerar el siguiente arranque; no conserva las aplicaciones y documentos abiertos.", null]],
  "ap25": ["Un técnico debe extender un volumen de datos hacia el espacio no asignado contiguo en el mismo disco usando una herramienta gráfica. ¿Qué herramienta debe abrir?", ["Liberador de espacio en disco", "Monitor de recursos", "Desfragmentar y optimizar unidades", "Administración de discos"], "Administración de discos (diskmgmt.msc) crea, formatea, extiende y reduce volúmenes. El Liberador de espacio en disco solo elimina archivos temporales.", ["El Liberador de espacio en disco libera espacio eliminando archivos temporales e innecesarios; no puede cambiar el tamaño ni extender volúmenes.", "El Monitor de recursos muestra en vivo el uso de CPU, memoria, disco y red; no administra volúmenes.", "Desfragmentar y optimizar unidades reorganiza los datos o aplica TRIM a los SSD; no puede cambiar el tamaño de un volumen.", null]],
  "ap26": ["La PC de un usuario muestra notas de rescate y muchos archivos tienen extensiones nuevas. Según el procedimiento de eliminación de malware de CompTIA, ¿qué debe hacer el técnico justo después de verificar los síntomas?", ["Educar al usuario", "Deshabilitar Restaurar sistema", "Poner en cuarentena el sistema infectado", "Ejecutar un análisis completo con definiciones actualizadas"], "El orden es investigar/verificar, poner en cuarentena, deshabilitar Restaurar sistema, remediar, programar análisis y actualizaciones, volver a habilitar Restaurar sistema y educar. Aislar la PC detiene la propagación.", ["Educar al usuario es el último paso del procedimiento, después de eliminar el malware.", "Deshabilitar Restaurar sistema viene después de poner en cuarentena el sistema, para que el malware no se propague mientras tanto.", null, "La remediación con herramientas actualizadas viene después de la cuarentena y de deshabilitar Restaurar sistema, no justo después de verificar los síntomas."]],
  "ap27": ["Durante la eliminación de malware, ¿por qué el técnico deshabilita Restaurar sistema antes de limpiar una PC con Windows?", ["Evita que el malware guardado en los puntos de restauración vuelva a aparecer después", "Acelera el análisis antimalware", "Windows no permite un análisis antimalware mientras Restaurar sistema está en ejecución", "Elimina el malware de la memoria"], "Los puntos de restauración pueden contener archivos infectados; eliminarlos al deshabilitar Restaurar sistema evita la reinfección a partir de una restauración.", [null, "Deshabilitar Restaurar sistema no es un ajuste de rendimiento; el objetivo es eliminar los puntos de restauración infectados.", "Windows permite ejecutar análisis antimalware con Restaurar sistema habilitado; lo que preocupa es la reinfección desde los puntos de restauración.", "Deshabilitar Restaurar sistema elimina los puntos de restauración en disco; no hace nada contra el malware que se ejecuta en memoria."]],
  "ap28": ["El malware fue eliminado y los análisis están programados. ¿Cuál es el paso final del procedimiento?", ["Volver a instalar la imagen del equipo", "Poner la PC nuevamente en cuarentena", "Deshabilitar la cuenta del usuario", "Educar al usuario final"], "Después de volver a habilitar Restaurar sistema y crear un punto de restauración limpio, el último paso es enseñar al usuario a evitar la reinfección.", ["Reinstalar la imagen es una opción de remediación cuando la limpieza falla; no es el paso de cierre del procedimiento.", "La cuarentena ocurre al principio del procedimiento; aislar de nuevo la PC limpia al final no tendría sentido.", "Deshabilitar la cuenta castiga al usuario sin corregir la causa; el procedimiento termina educándolo.", null]],
  "ap29": ["Una carpeta compartida otorga a Everyone Control total a nivel de recurso compartido, mientras que NTFS da al grupo Sales permiso de Lectura. ¿Qué acceso tiene un usuario de Sales a través de la red?", ["Control total", "Ningún acceso", "Modificar", "Lectura"], "Cuando se combinan los permisos de recurso compartido y NTFS, se aplica el más restrictivo, así que el usuario obtiene Lectura.", ["Control total es solo el permiso del recurso compartido; el permiso NTFS de Lectura, más restrictivo, limita al usuario.", "El usuario tiene permisos en ambos niveles, así que el acceso no se niega; el resultado combinado es Lectura.", "Ni los permisos del recurso compartido ni los de NTFS otorgan Modificar, así que el usuario no puede obtenerlo.", null]],
  "ap30": ["Un archivo con permisos NTFS se mueve a otra carpeta del mismo volumen NTFS. ¿Qué pasa con sus permisos?", ["Se reemplazan por los permisos del destino", "Se restablecen a Everyone Control total", "El archivo conserva sus permisos originales", "El archivo se vuelve de solo lectura"], "Un movimiento dentro del mismo volumen conserva los permisos del archivo. Una copia, o un movimiento a otro volumen, toma los permisos heredados del destino.", ["Heredar los permisos del destino ocurre en una copia o en un movimiento a otro volumen, no en un movimiento dentro del mismo volumen.", "Windows nunca restablece los permisos a Everyone Control total al mover archivos.", null, "Mover un archivo no activa su atributo de solo lectura; sus permisos NTFS quedan como estaban."]],
  "ap31": ["Una empresa quiere que las memorias USB estén cifradas con contraseña para que los datos estén protegidos si se pierde una. ¿Qué función de Windows es adecuada?", ["EFS", "Windows Hello", "Control de cuentas de usuario", "BitLocker To Go"], "BitLocker To Go cifra unidades extraíbles. EFS cifra archivos individuales de un usuario en volúmenes NTFS, y UAC controla los avisos de elevación.", ["EFS cifra archivos individuales de un usuario en volúmenes NTFS; no está diseñado para proteger con contraseña unidades extraíbles completas.", "Windows Hello es el inicio de sesión biométrico o con PIN en Windows; no cifra unidades USB.", "El Control de cuentas de usuario avisa antes de elevar privilegios; no ofrece ningún cifrado.", null]],
  "ap32": ["Los usuarios suelen trabajar como administradores locales y el malware instala software silenciosamente. ¿Qué control aplica MEJOR el mínimo privilegio?", ["Dar a los usuarios cuentas estándar y mantener UAC habilitado", "Desactivar Windows Defender Firewall", "Habilitar la cuenta Invitado", "Agregar a los usuarios al grupo local Power Users en lugar de Administradores"], "Las cuentas estándar con avisos de UAC para la elevación impiden que el software se instale silenciosamente con derechos de administrador.", [null, "Desactivar el firewall debilita la seguridad y no impide que el software se instale con derechos de administrador.", "La cuenta Invitado agrega una forma de iniciar sesión sin autenticación, lo que aumenta el riesgo en lugar de aplicar el mínimo privilegio.", "Power Users es un grupo heredado que aún tiene derechos elevados; no es un tipo de cuenta de mínimo privilegio."]],
  "ap33": ["Una oficina que reemplaza su Wi-Fi quiere que cada empleado inicie sesión con sus propias credenciales de directorio en lugar de una frase de acceso compartida. ¿Qué debe usar?", ["WPA2-Personal con TKIP", "WPA3-Enterprise con RADIUS", "WPA3-Personal con SAE", "Una red abierta con filtrado MAC"], "El modo Enterprise usa 802.1X con un servidor RADIUS para que cada usuario se autentique individualmente. Los modos Personal usan una sola frase de acceso compartida.", ["WPA2-Personal usa una sola frase de acceso compartida para todos, y TKIP es un cifrado débil y obsoleto.", null, "WPA3-Personal con SAE es más fuerte que WPA2-Personal, pero sigue usando una frase de acceso compartida, no credenciales por usuario.", "Una red abierta no tiene cifrado, y el filtrado MAC se evade fácilmente con suplantación; no ofrece inicio de sesión por usuario."]],
  "ap34": ["¿Qué protocolo de autenticación usa tickets emitidos por un centro de distribución de claves y se utiliza en los inicios de sesión de dominio de Active Directory?", ["RADIUS", "TACACS+", "Kerberos", "Diameter"], "Kerberos emite tickets de tiempo limitado desde el KDC del controlador de dominio. RADIUS y TACACS+ son protocolos AAA para acceso a la red y administración de dispositivos.", ["RADIUS es un protocolo AAA para acceso a la red, como Wi-Fi y VPN; no usa tickets de un KDC.", "TACACS+ es un protocolo AAA para administrar dispositivos de red; no emite tickets para inicios de sesión de dominio.", null, "Diameter es un sucesor de RADIUS usado principalmente en redes de telecomunicaciones; no se usa para inicios de sesión de Active Directory."]],
  "ap35": ["Los administradores de red necesitan un protocolo AAA para iniciar sesión en switches y routers que cifre toda la carga útil y separe la autorización de la autenticación. ¿Qué protocolo es adecuado?", ["LDAP", "RADIUS", "Kerberos", "TACACS+"], "TACACS+ cifra el paquete completo y maneja por separado la autenticación, la autorización y la contabilidad, lo que es adecuado para administrar dispositivos. RADIUS cifra solo la contraseña.", ["LDAP es un protocolo de consulta de directorios; no es un protocolo AAA y no separa la autorización de la autenticación.", "RADIUS cifra solo la contraseña y combina la autenticación con la autorización, así que no cumple los requisitos.", "Kerberos maneja la autenticación con tickets para recursos del dominio; no es el protocolo AAA usado para iniciar sesión en switches y routers.", null]],
  "ap36": ["La PC de un usuario no muestra síntomas, pero una herramienta detecta que un programa oculto a nivel de kernel está escondiendo procesos del Administrador de tareas. ¿Qué tipo de malware es?", ["Adware", "Keylogger", "Rootkit", "Cryptominer"], "Los rootkits se ocultan a bajo nivel, a menudo en el kernel o en el proceso de arranque, y esconden sus archivos y procesos de las herramientas normales.", ["El adware muestra anuncios no deseados y suele ser muy visible; normalmente no se oculta a nivel de kernel.", "Un keylogger registra las pulsaciones de teclas; ocultar procesos a nivel de kernel es el rasgo que define a otro tipo.", null, "Un cryptominer usa mucho la CPU o la GPU, lo que causaría síntomas evidentes; esconder procesos define a un rootkit."]],
  "ap37": ["La CPU de una PC funciona cerca del 100% incluso en reposo, el ventilador hace mucho ruido y no hay ninguna aplicación evidente abierta. ¿Qué malware es el MÁS probable?", ["Spyware", "Ransomware", "Virus del sector de arranque", "Cryptominer"], "Los cryptominers usan ciclos de CPU o GPU para minar criptomonedas, lo que causa una carga alta constante. El ransomware cifraría archivos y exigiría un pago.", ["El spyware recopila información en silencio y normalmente no causa una carga de CPU constante cercana al 100%.", "El ransomware cifra archivos y muestra una exigencia de rescate, que no es el síntoma descrito.", "Un virus del sector de arranque infecta el código de inicio y causa problemas de arranque, no un uso alto y constante de CPU en reposo.", null]],
  "ap38": ["Un empleado recibe un mensaje de texto que dice que su cuenta de nómina está bloqueada, con un enlace para iniciar sesión. ¿Qué ataque es este?", ["Vishing", "Whaling", "Smishing", "Tailgating"], "El smishing es phishing por SMS. El vishing usa llamadas de voz, y el whaling se dirige a altos ejecutivos.", ["El vishing es phishing por llamada de voz, pero este ataque llegó como mensaje de texto.", "El whaling se dirige a altos ejecutivos, normalmente por correo; este es un texto genérico enviado a un empleado.", null, "El tailgating es seguir a una persona autorizada a través de una puerta segura; es un ataque físico, no un mensaje."]],
  "ap39": ["Un póster en la sala de descanso tiene un código QR que ofrece un cupón de almuerzo gratis, el cual lleva a una página falsa de inicio de sesión de la empresa. ¿Qué es esto?", ["Evil twin", "Phishing con código QR", "Dumpster diving", "Shoulder surfing"], "El phishing con código QR oculta una URL maliciosa en un código QR para que los usuarios no puedan revisar fácilmente el enlace antes de escanearlo.", ["Un evil twin es un access point Wi-Fi falso que copia un SSID real; no involucra ningún código QR.", null, "El dumpster diving es buscar información útil en la basura; no implica atraer usuarios a una página falsa.", "El shoulder surfing es mirar la pantalla o el teclado de alguien para robar información, no colocar un enlace malicioso."]],
  "ap40": ["Un atacante configura un hotspot en el vestíbulo con el mismo nombre que el Wi-Fi de invitados de la empresa para capturar tráfico. ¿Qué es esto?", ["Exploit de día cero", "Ataque de fuerza bruta", "Inyección SQL", "Evil twin"], "Un evil twin es un access point falso que copia un SSID legítimo para que los usuarios se conecten a él.", ["Un exploit de día cero ataca una falla de software desconocida y sin parche; no implica un hotspot falso.", "Un ataque de fuerza bruta adivina contraseñas o claves repetidamente; no imita una red Wi-Fi.", "La inyección SQL envía datos maliciosos a una aplicación con base de datos, no a una red inalámbrica falsa.", null]],
  "ap41": ["El equipo de cuentas por pagar recibe un correo que parece venir del buzón real de un proveedor habitual, pidiéndoles cambiar la cuenta bancaria para el pago de facturas. ¿Qué ataque es este?", ["Denegación de servicio distribuida", "Cross-site scripting", "Business email compromise", "Suplantación por teléfono"], "BEC usa un buzón empresarial comprometido o suplantado para desviar pagos. Hay que verificar cualquier cambio bancario llamando a un número conocido.", ["Un DDoS inunda un servicio con tráfico para dejarlo fuera de línea; no engaña al personal para desviar pagos.", "El cross-site scripting inyecta scripts maliciosos en páginas web que ven otros; no es un fraude de pagos por correo.", null, "La suplantación por teléfono es vishing; este ataque llegó por el buzón de correo del proveedor, no por una llamada."]],
  "ap42": ["Discos duros viejos con datos de clientes deben destruirse para que un proveedor de reutilización no pueda recuperar nada, y la empresa necesita un comprobante. ¿Cuál es el MEJOR enfoque?", ["Hacer un formateo completo de cada disco y luego donarlos todos a una escuela local", "Eliminar las particiones con diskpart", "Mover los archivos a la Papelera de reciclaje y vaciarla", "Hacer que un proveedor certificado los triture y emita un certificado de destrucción"], "La trituración física hace que los datos sean irrecuperables, y un certificado de destrucción lo documenta. Formatear y eliminar dejan datos recuperables.", ["Un formateo completo puede dejar datos recuperables con herramientas forenses, y donar los discos no ofrece ninguna prueba de destrucción.", "Eliminar particiones solo borra la tabla de particiones; los datos siguen en los platos y se recuperan fácilmente.", "Vaciar la Papelera de reciclaje solo marca el espacio como libre; los archivos siguen siendo recuperables y no hay comprobante.", null]],
  "ap43": ["Un técnico planea desmagnetizar (degauss) un lote de SSD retirados. ¿Por qué es una mala elección?", ["Los SSD almacenan datos en memoria flash, no magnéticamente", "La desmagnetización anula la garantía", "La desmagnetización solo funciona en discos cifrados", "Los SSD deben formatearse y particionarse antes de poder desmagnetizarse"], "La desmagnetización destruye medios magnéticos como HDD y cintas. Los SSD necesitan secure erase, crypto-erase o destrucción física.", [null, "La garantía de discos retirados es irrelevante; el verdadero problema es que la desmagnetización no afecta el almacenamiento flash.", "La desmagnetización funciona en medios magnéticos estén cifrados o no; el cifrado no tiene nada que ver.", "Formatear o particionar no hace que un SSD sea vulnerable a la desmagnetización; la memoria flash no es magnética."]],
  "ap44": ["¿Qué cambio en un router SOHO nuevo es el MÁS importante de hacer PRIMERO?", ["Habilitar UPnP para las consolas de videojuegos", "Ocultar el SSID", "Cambiar la contraseña de administrador predeterminada", "Activar WPS para que los nuevos dispositivos se emparejen con solo presionar un botón"], "Las credenciales de administrador predeterminadas son de conocimiento público. UPnP y WPS debilitan la seguridad, y ocultar el SSID aporta poca protección.", ["UPnP permite que los dispositivos abran puertos del router automáticamente, lo que debilita la seguridad en lugar de mejorarla.", "Ocultar el SSID aporta poca protección, porque el nombre de la red se puede encontrar con herramientas inalámbricas simples.", null, "El emparejamiento WPS por botón y por PIN tiene debilidades conocidas, así que habilitarlo reduce la seguridad."]],
  "ap45": ["Un usuario doméstico quiere que la aplicación de su cámara de seguridad sea accesible desde internet en TCP 8443 a través del router. ¿Qué debe configurarse?", ["Solo una reserva DHCP", "Filtrado de contenido para el tráfico web de la cámara", "Port forwarding a la IP de la cámara", "Una red de invitados"], "Port forwarding envía el tráfico entrante de un puerto a un host interno; conviene combinarlo con una reserva DHCP para que la dirección no cambie.", ["Una reserva DHCP solo mantiene fija la dirección IP de la cámara; no permite que el tráfico entrante de internet llegue a ella.", "El filtrado de contenido bloquea o permite contenido web saliente; no abre un puerto entrante hacia la cámara.", null, "Una red de invitados aísla los dispositivos de los visitantes; no hace que un dispositivo interno sea accesible desde internet."]],
  "ap46": ["Un usuario descargó un instalador desde un sitio espejo. ¿Cómo puede confirmar que el archivo no fue alterado?", ["Verificar que el nombre del archivo y el ícono coincidan con el nombre del producto", "Comparar su hash con el publicado por el fabricante", "Verificar que la descarga haya usado HTTP", "Hacer clic derecho y elegir Ejecutar como administrador"], "Un hash SHA-256 que coincide demuestra que el archivo es idéntico al publicado por el fabricante.", ["Un atacante puede mantener fácilmente el mismo nombre de archivo e ícono en un instalador modificado, así que no prueban nada.", null, "HTTP no está cifrado y no verifica la integridad, así que no ofrece ninguna prueba de que el archivo no se haya cambiado.", "Ejecutar como administrador le da al archivo más poder sobre el sistema; no verifica nada y aumenta el riesgo."]],
  "ap47": ["Una empresa quiere poder localizar y borrar los teléfonos corporativos perdidos, y exigir bloqueo de pantalla y cifrado en todos los dispositivos. ¿Qué debe implementar?", ["Un cliente VPN en cada teléfono", "Un gestor de contraseñas", "Mobile device management", "Emparejamiento Bluetooth"], "MDM aplica políticas como códigos de acceso y cifrado y permite localizar y borrar remotamente.", ["Un cliente VPN cifra el tráfico de red, pero no puede localizar, borrar ni exigir bloqueos de pantalla en un teléfono.", "Un gestor de contraseñas almacena credenciales de forma segura; no puede aplicar políticas de dispositivos ni borrar teléfonos remotamente.", null, "El emparejamiento Bluetooth conecta accesorios a un teléfono; no tiene capacidad de administración de dispositivos."]],
  "ap48": ["¿Qué medida de hardening de estaciones de trabajo impide que el malware de una memoria USB insertada se inicie automáticamente?", ["Habilitar el escritorio remoto", "Habilitar la cuenta Invitado", "Desactivar el bloqueo del protector de pantalla", "Deshabilitar AutoRun/AutoPlay"], "Deshabilitar AutoRun y AutoPlay impide que los medios ejecuten contenido al insertarse.", ["Habilitar Remote Desktop abre una vía de acceso remoto, lo que agrega superficie de ataque y no hace nada respecto a los medios USB.", "La cuenta Invitado permite inicios de sesión sin autenticación, lo que debilita la seguridad y no afecta la ejecución automática de USB.", "Desactivar el bloqueo del protector de pantalla deja las PC desatendidas abiertas a cualquiera; no impide que el malware USB se inicie.", null]],
  "ap49": ["Los empleados deben pasar su credencial en una puerta, esperar en un cuarto pequeño hasta que esa puerta se cierre y luego volver a pasar la credencial en una segunda puerta. ¿Qué control es este?", ["Bolardo", "Vestíbulo de control de acceso", "Lector de credenciales con sensor de movimiento", "Videovigilancia"], "Un vestíbulo de control de acceso (mantrap) permite que solo se abra una puerta a la vez, lo que impide el tailgating.", ["Los bolardos son postes cortos y resistentes que impiden que los vehículos lleguen a un edificio; no controlan a las personas en las puertas.", null, "Un lector de credenciales con sensor de movimiento controla una sola puerta; no crea el espacio de dos puertas, una a la vez, que se describe.", "La videovigilancia graba la actividad, pero no impide físicamente que alguien entre."]],
  "ap50": ["Una empresa quiere impedir que los empleados envíen por correo fuera de la organización archivos que contengan números de tarjetas de crédito. ¿Qué control es adecuado?", ["Prevención de pérdida de datos", "Single sign-on", "Servicios de directorio con Group Policy", "Política de bloqueo de pantalla"], "DLP inspecciona los datos salientes en busca de patrones sensibles, como números de tarjeta, y los bloquea o marca.", [null, "Single sign-on permite iniciar sesión una vez para acceder a muchas aplicaciones; no inspecciona los datos salientes.", "Los servicios de directorio y Group Policy administran cuentas y configuraciones; no analizan el contenido del correo en busca de números de tarjeta.", "Una política de bloqueo de pantalla protege las PC desatendidas; no impide que se envíen datos sensibles por correo."]],
  "ap51": ["Después de una actualización del driver de gráficos, una PC con Windows muestra una pantalla azul en cada arranque normal. ¿Qué debe hacer el técnico PRIMERO?", ["Reemplazar la tarjeta de video", "Arrancar en Modo seguro y revertir el driver", "Reinstalar Windows desde cero", "Ejecutar chkdsk /r desde el escritorio después del siguiente reinicio"], "El Modo seguro carga drivers básicos, así que se puede revertir el driver defectuoso. Reinstalar o reemplazar hardware es prematuro.", ["Reemplazar la tarjeta de video es prematuro; las fallas comenzaron después de una actualización de driver, lo que apunta al software.", null, "Reinstalar Windows es un paso drástico que hace perder tiempo y configuración cuando revertir un solo driver debería resolverlo.", "La PC no puede llegar al escritorio porque falla en cada arranque, y chkdsk corrige errores de disco, no fallas de drivers."]],
  "ap52": ["Una PC empezó a fallar después de la actualización acumulativa de Windows de esta semana. El usuario la necesita funcionando hoy. ¿Cuál es la MEJOR solución?", ["Desinstalar la actualización de calidad más reciente desde Windows Update o WinRE", "Deshabilitar Windows Update de forma permanente", "Reinstalar la imagen de la PC sin actualizaciones", "Reemplazar la RAM"], "Revertir la actualización problemática corrige la regresión rápidamente. Deshabilitar las actualizaciones de forma permanente deja expuesta la PC.", [null, "Deshabilitar Windows Update de forma permanente deja la PC sin correcciones de seguridad; tampoco corrige la falla actual.", "Reinstalar la imagen toma mucho más tiempo que quitar una actualización, y una PC sin actualizaciones queda expuesta.", "Las fallas comenzaron con una actualización de software, así que reemplazar la RAM no atacaría la causa probable."]],
  "ap53": ["Un servicio que requiere una aplicación contable no inicia después de los reinicios, y el Visor de eventos muestra que falló una dependencia. ¿Qué debe revisar el técnico?", ["La resolución de pantalla", "La cola del spooler de impresión y la impresora predeterminada", "Los servicios de los que depende en services.msc", "La configuración del fondo de pantalla del usuario"], "Un servicio no inicia si un servicio del que depende está detenido o deshabilitado; la pestaña Dependencias los enumera.", ["La resolución de pantalla solo afecta la salida de video; no influye en si un servicio de Windows puede iniciar.", "El spooler de impresión y la impresora predeterminada afectan la impresión, no una dependencia fallida de un servicio contable.", null, "La configuración del fondo de pantalla es una preferencia estética del usuario y no puede causar una falla de dependencia de un servicio."]],
  "ap54": ["La PC de un usuario está muy lenta. El Administrador de tareas muestra la memoria al 98% y mucha actividad de disco mientras hay varias aplicaciones grandes abiertas. ¿Cuál es la MEJOR solución a largo plazo?", ["Ejecutar el Liberador de espacio en disco", "Agregar más RAM", "Desfragmentar el SSD", "Deshabilitar el archivo de paginación"], "El uso constante y alto de memoria obliga a paginar en disco, lo que causa la lentitud. Más RAM corrige la causa raíz; deshabilitar el archivo de paginación provocaría fallas.", ["El Liberador de espacio en disco libera almacenamiento, pero el problema es la presión sobre la memoria, no un disco lleno.", null, "Los SSD no deben desfragmentarse (Windows les aplica TRIM), y la lentitud viene de la paginación por falta de RAM.", "Deshabilitar el archivo de paginación elimina el espacio de desborde de la memoria, lo que haría que las aplicaciones fallen cuando se acabe la RAM."]],
  "ap55": ["Una PC muestra 'Operating system not found' después de que un técnico agregó un segundo disco. No cambió nada más. ¿Cuál es la causa MÁS probable?", ["El orden de arranque ahora pone primero el disco nuevo", "El cable del monitor está flojo", "La licencia de Windows expiró al cambiar el hardware", "El servidor DNS está caído"], "Agregar un disco puede cambiar el orden de arranque del firmware; hay que poner primero el disco del sistema operativo en UEFI/BIOS.", [null, "Un cable de monitor flojo causaría una pantalla en negro o con parpadeo, no un mensaje del firmware 'Operating system not found'.", "La licencia de Windows no impide que se encuentre el cargador de arranque; un problema de licencia aparece después de que Windows carga.", "El DNS se usa para resolver nombres en la red; la PC todavía no ha cargado un sistema operativo, así que los servicios de red no intervienen."]],
  "ap56": ["El reloj de un usuario se desfasa varios minutos constantemente, y no puede iniciar sesión en el dominio hasta que se corrige. ¿Qué debe revisar el técnico?", ["La tasa de refresco de la pantalla", "Si el servicio Hora de Windows se sincroniza con una fuente NTP válida", "El tamaño del archivo de paginación", "El bloqueador de ventanas emergentes del navegador"], "Kerberos rechaza los inicios de sesión cuando los relojes difieren demasiado. Hora de Windows debe sincronizarse (w32tm /resync), y una batería CMOS que falla también puede causar desfase.", ["La tasa de refresco solo afecta con qué frecuencia se redibuja la pantalla; no tiene nada que ver con el reloj del sistema.", null, "El archivo de paginación es memoria virtual; su tamaño no afecta la precisión del reloj ni los inicios de sesión del dominio.", "El bloqueador de ventanas emergentes solo afecta las páginas web; no interviene en la sincronización de la hora ni en los inicios de sesión Kerberos."]],
  "ap57": ["Solo un usuario de una PC compartida obtiene un perfil temporal en cada inicio de sesión y pierde la configuración de su escritorio. Los demás usuarios están bien. ¿Cuál es la MEJOR solución?", ["Reinstalar Windows", "Reemplazar el disco duro", "Reconstruir el perfil del usuario", "Restablecer el BIOS a los valores predeterminados"], "Un perfil dañado causa perfiles temporales solo para ese usuario. Hay que respaldar los datos y luego reconstruir el perfil.", ["Los demás usuarios de la misma PC funcionan bien, así que el sistema operativo está sano y reinstalarlo es excesivo.", "Un disco duro que falla afectaría a todos los usuarios, no a un solo perfil.", null, "La configuración del BIOS se aplica a todo el equipo, así que restablecerla no puede corregir el perfil dañado de un usuario."]],
  "ap58": ["Windows advierte que un controlador USB se quedó sin recursos cuando un usuario conecta un dock, una webcam y dos discos a un solo hub. ¿Qué debe intentar?", ["Actualizar la contraseña del BIOS", "Repartir los dispositivos entre puertos USB de controladores diferentes", "Deshabilitar Windows Firewall", "Cambiar el plan de energía a Equilibrado"], "Cada controlador USB tiene endpoints limitados; mover dispositivos a puertos de otros controladores (o quitar el hub) elimina la advertencia.", ["Una contraseña del BIOS controla el acceso a la configuración del firmware; no tiene nada que ver con los recursos del controlador USB.", null, "Windows Firewall filtra el tráfico de red; no afecta los endpoints del controlador USB.", "Los planes de energía cambian el rendimiento y la suspensión; no le dan más endpoints a un controlador USB."]],
  "ap59": ["Una aplicación del teléfono se cierra de inmediato cada vez que se abre. Reiniciar el teléfono no ayudó. ¿Qué debe intentar el técnico a continuación?", ["Borrar la caché y los datos de la aplicación o reinstalarla", "Restablecer el teléfono de fábrica", "Reemplazar la batería", "Activar el modo avión"], "Borrar la caché de la aplicación o reinstalarla corrige los datos dañados de la aplicación sin la pérdida de datos de un restablecimiento de fábrica.", [null, "Un restablecimiento de fábrica borra todos los datos del teléfono, lo cual es excesivo cuando solo falla una aplicación.", "Una batería desgastada afecta la duración de la batería y los apagados, no que una aplicación se cierre al abrirla.", "El modo avión apaga los radios inalámbricos; no corregirá datos dañados que hacen fallar la aplicación."]],
  "ap60": ["La batería del teléfono de un usuario ahora dura medio día. La configuración de batería muestra que una red social consumió la mayor parte de la energía en segundo plano. ¿Cuál es la MEJOR solución?", ["Reemplazar el teléfono", "Restringir la actividad en segundo plano de la aplicación o actualizarla", "Apagar el Wi-Fi de forma permanente", "Bajar el brillo de la pantalla a cero y activar el modo oscuro"], "El uso de batería muestra la culpable; limitar la actualización en segundo plano o actualizar la aplicación problemática la resuelve directamente.", ["Reemplazar el teléfono es costoso e innecesario cuando la actividad en segundo plano de una aplicación es claramente la causa.", null, "Apagar el Wi-Fi a menudo aumenta el consumo de batería porque el teléfono usa datos celulares, y además ignora la aplicación que lo causa.", "El brillo mínimo y el modo oscuro reducen el consumo de la pantalla, pero el problema es el uso en segundo plano de una aplicación, no la pantalla."]],
  "ap61": ["La pantalla de una tablet no gira al ponerla de lado en ninguna aplicación. ¿Qué debe revisarse PRIMERO?", ["Si el bloqueo de rotación está activado", "La lista de emparejamiento Bluetooth", "El espacio de almacenamiento disponible", "La banda Wi-Fi"], "El bloqueo de rotación en la configuración rápida mantiene la pantalla en una sola orientación; es la causa más común.", [null, "La lista de emparejamiento Bluetooth solo controla las conexiones de accesorios inalámbricos; no afecta la orientación de la pantalla.", "El almacenamiento disponible no afecta si la pantalla gira con el dispositivo.", "La banda Wi-Fi cambia la velocidad y el alcance de la conexión; no afecta la rotación de la pantalla."]],
  "ap62": ["Un usuario instaló una aplicación desde un enlace de un sitio web en lugar de la tienda oficial. Ahora el teléfono muestra falsas alertas de virus y usa muchos más datos. ¿Cuál es la causa MÁS probable?", ["Una batería que falla", "Una aplicación maliciosa instalada por sideloading", "Una señal Wi-Fi débil que obliga a usar datos celulares", "Una tarjeta SIM vencida"], "Las aplicaciones instaladas por sideloading fuera de la tienda oficial evitan la revisión y a menudo traen malware que causa alertas falsas y tráfico adicional.", ["Una batería que falla causa poca duración o apagados, no falsas alertas de virus ni uso adicional de datos.", null, "Una señal Wi-Fi débil puede aumentar el uso de datos celulares, pero no causaría falsas ventanas de virus.", "Una SIM vencida o defectuosa detiene el servicio celular; no genera alertas falsas ni tráfico adicional."]],
  "ap63": ["El teléfono de un empleado fue rooteado para instalar temas personalizados. ¿Por qué es una preocupación de seguridad para la empresa?", ["El rooteo acelera el procesador", "El rooteo bloquea todas las actualizaciones de aplicaciones", "El rooteo evade los controles de seguridad del sistema operativo y puede romper la aplicación de MDM", "El rooteo deshabilita el Bluetooth"], "El rooteo o jailbreak elimina el sandboxing y las restricciones integradas, lo que permite que las aplicaciones obtengan control total y que los usuarios eviten las políticas de MDM.", ["El rooteo no acelera el procesador; cualquier ajuste que permita es un efecto secundario, no una preocupación de seguridad.", "Los teléfonos rooteados aún pueden recibir actualizaciones de aplicaciones; la preocupación es la pérdida de los controles de seguridad del sistema.", null, "El rooteo no deshabilita el Bluetooth; la preocupación de seguridad es evadir las protecciones del sistema y MDM."]],
  "ap64": ["El navegador de un usuario muestra una advertencia de certificado en el sitio de su banco, pero solo en la red de la oficina. Otros sitios funcionan bien. ¿Qué debe sospechar el técnico?", ["La caché del navegador está llena", "El sitio está siendo interceptado o el proxy está mal configurado", "Las contraseñas guardadas del banco en el navegador expiraron y deben restablecerse", "La PC necesita más RAM"], "Un error de certificado en una sola red puede indicar un ataque on-path o un proxy de inspección mal configurado. Los usuarios no deben ignorar la advertencia y continuar.", ["Una caché llena puede hacer lentas las páginas, pero no causa advertencias de certificado, y menos solo en una red.", null, "Las contraseñas guardadas no tienen nada que ver con la validación de certificados, y no expiran de una forma que cause advertencias.", "La RAM no afecta la validación de certificados; la advertencia depende de la red en la que está la PC."]],
  "ap65": ["Cada búsqueda en el navegador de un usuario va a un sitio de búsqueda desconocido, y apareció una nueva barra de herramientas. ¿Qué debe hacer el técnico PRIMERO?", ["Reinstalar el sistema operativo", "Reemplazar la tarjeta de red", "Cambiar la contraseña del correo del usuario", "Quitar las extensiones desconocidas y restablecer la configuración de búsqueda y página de inicio del navegador"], "La redirección y las barras de herramientas suelen venir de una extensión maliciosa o de una configuración secuestrada. Hay que quitarlas y luego buscar malware.", ["Reinstalar el sistema operativo es un paso drástico y lento cuando el problema suele ser una extensión o la configuración del navegador.", "La tarjeta de red no puede cambiar el motor de búsqueda del navegador ni agregar barras de herramientas.", "Cambiar la contraseña del correo no tiene relación con la redirección del navegador y no quita la extensión maliciosa.", null]],
  "ap66": ["Una ventana emergente afirma que la PC está infectada y le dice al usuario que llame a un número de soporte. El antivirus instalado no muestra alertas. ¿Qué es esto MÁS probablemente?", ["Una alerta real de Windows Defender", "Una advertencia genuina del diagnóstico de hardware de la PC", "Una alerta de seguridad falsa (scareware)", "Un aviso de Windows Update"], "Las alertas antivirus falsas empujan a los usuarios a llamar a estafadores o a instalar malware. Hay que cerrar el navegador y ejecutar un análisis con el antivirus real.", ["Las alertas reales de Windows Defender aparecen en la aplicación Seguridad de Windows y nunca piden llamar a un número telefónico.", "El diagnóstico de hardware informa fallas de componentes; no muestra ventanas de virus con números de soporte.", null, "Los avisos de Windows Update anuncian actualizaciones; nunca afirman que hay infecciones ni dan un número de soporte."]],
  "ap67": ["Después de limpiar malware, una PC sigue sin poder acceder a ningún sitio web, aunque tiene una IP válida. El técnico encuentra un proxy configurado en 127.0.0.1:8080. ¿Qué debe hacer?", ["Quitar la configuración del proxy y revisar el archivo hosts", "Reemplazar el cable Ethernet", "Solo renovar el lease DHCP", "Deshabilitar el firewall"], "El malware a menudo configura un proxy falso o entradas en hosts para secuestrar el tráfico. Hay que eliminarlos después de quitar el malware.", [null, "Un cable dañado cortaría el enlace por completo; la PC tiene una IP válida, así que la conexión física funciona.", "Renovar el lease DHCP da una nueva IP, pero deja el proxy falso en su lugar, así que el tráfico web sigue fallando.", "Deshabilitar el firewall debilita la seguridad y no quita el proxy falso que bloquea el tráfico web."]],
  "ap68": ["Las actualizaciones de Windows siguen fallando en una PC que tuvo malware recientemente, y algunos archivos del sistema parecen renombrados. ¿Cuál es la explicación MÁS probable?", ["El servidor de actualizaciones está fuera de línea para todos", "El malware alteró archivos del sistema y bloqueó las actualizaciones", "La PC está en una conexión de uso medido", "La zona horaria está mal configurada"], "El malware a menudo manipula los archivos del sistema y los servicios de actualización para evitar ser eliminado. Hay que ejecutar sfc y DISM, o reinstalar la imagen si no se puede confiar en el sistema.", ["Una caída para todos es poco probable y no explicaría archivos del sistema renombrados en esta PC después del malware.", null, "Una conexión de uso medido solo pospone algunas descargas de actualizaciones; no hace que fallen ni renombra archivos del sistema.", "Una zona horaria incorrecta no hace fallar las actualizaciones ni renombra archivos (un reloj muy desfasado podría romper TLS, pero no renombrar archivos)."]],
  "ap69": ["Una aplicación falla varias veces al día. ¿Dónde puede el técnico ver una línea de tiempo de fallas de aplicaciones y cambios de Windows para encontrar qué cambió?", ["Monitor de confiabilidad", "Administración de discos", "Administrador de dispositivos", "Directiva de seguridad local"], "El Monitor de confiabilidad grafica por día los bloqueos, las fallas y las instalaciones, lo que facilita relacionar un bloqueo con un cambio reciente.", [null, "Administración de discos maneja discos y volúmenes; no guarda historial de bloqueos de aplicaciones ni cambios del sistema.", "El Administrador de dispositivos muestra hardware y drivers; no ofrece una línea de tiempo de fallas de aplicaciones.", "La Directiva de seguridad local define configuraciones de seguridad como políticas de contraseñas y auditoría; no registra bloqueos."]],
  "ap70": ["Una laptop se apaga sin aviso, sobre todo mientras se juega, y el Visor de eventos muestra errores Kernel-Power. ¿Qué debe revisarse PRIMERO?", ["La antigüedad de la contraseña del usuario", "Sobrecalentamiento: rejillas, ventiladores y lecturas térmicas", "La configuración de brillo y del tiempo de espera de la pantalla", "La edición de Windows"], "Los apagados inesperados bajo carga suelen deberse a la protección contra sobrecalentamiento. Hay que limpiar las rejillas y revisar ventiladores y temperaturas.", ["La antigüedad de la contraseña no tiene nada que ver con que la laptop se apague bajo carga.", null, "El brillo y el tiempo de espera controlan cuándo se atenúa o apaga la pantalla; no cortan la energía de repente durante un juego.", "La edición de Windows no causa apagados repentinos bajo carga; los causan el calor o problemas de energía."]],
  "ap71": ["Un usuario no puede conectar sus audífonos inalámbricos al teléfono, aunque funcionaban ayer. El Bluetooth está activado. ¿Cuál es un buen primer paso?", ["Restablecer el teléfono de fábrica", "Quitar (olvidar) los audífonos y emparejarlos de nuevo", "Deshabilitar las llamadas por Wi-Fi", "Instalar una aplicación de una tienda de terceros"], "Olvidar el dispositivo y volver a emparejarlo elimina un registro de emparejamiento dañado; es rápido y no destructivo.", ["Un restablecimiento de fábrica borra el teléfono, lo cual es demasiado drástico para un problema de emparejamiento con un accesorio.", null, "Las llamadas por Wi-Fi enrutan las llamadas por Wi-Fi; deshabilitarlas no afecta el emparejamiento Bluetooth.", "Las tiendas de terceros agregan riesgo de malware, y no se necesita ninguna aplicación adicional para emparejar audífonos Bluetooth."]],
  "ap72": ["Un técnico está cerrando un ticket. ¿Qué deben incluir las notas de resolución?", ["Solo la palabra 'solucionado'", "La contraseña del usuario", "Una descripción clara del problema, los pasos realizados y la solución final", "Una opinión personal sobre cómo el usuario probablemente causó el problema"], "Las buenas notas permiten que otros entiendan lo que pasó y reutilicen la solución. Nunca se deben registrar contraseñas en los tickets.", ["'Solucionado' no da a otros técnicos ninguna información sobre el problema o la solución, así que no se puede reutilizar.", "Las contraseñas nunca deben registrarse en los tickets, ya que cualquiera con acceso a los tickets podría leerlas.", null, "Las opiniones personales que culpan al usuario no son profesionales y no ayudan a nadie a resolver problemas similares."]],
  "ap73": ["TI necesita un registro central de cada laptop, quién la tiene, su fecha de garantía y su configuración. ¿Qué debe usar?", ["Una base de datos de gestión de activos (CMDB) con etiquetas de activo", "Un fondo de pantalla compartido", "La tabla de leases DHCP", "Una lista telefónica impresa"], "La gestión de activos con etiquetas y una CMDB registra los dispositivos, los usuarios asignados, la garantía y la configuración.", [null, "El fondo de pantalla puede mostrar el nombre de un equipo en una pantalla, pero no sirve como registro central y consultable de activos.", "La tabla de leases DHCP solo muestra las asignaciones actuales de IP a MAC; no tiene datos de propietario, garantía ni configuración.", "Una lista telefónica impresa registra contactos, no dispositivos, y no puede consultarse ni mantenerse actualizada de forma central."]],
  "ap74": ["El primer día de un nuevo empleado requiere una cuenta, una laptop, correo y acceso al edificio. ¿Qué documento mantiene esto consistente cada vez?", ["Un informe de incidente", "Una política de uso aceptable", "Un acuerdo de nivel de servicio", "Una lista de verificación de incorporación (onboarding)"], "Una lista de verificación de incorporación (configuración de nuevo usuario) enumera cada paso para que no se omita nada. La AUP define el uso permitido de los sistemas.", ["Un informe de incidente documenta un evento como una caída o una brecha después de que ocurre, no los pasos de configuración de un nuevo empleado.", "Una política de uso aceptable define qué pueden hacer los usuarios con los sistemas de la empresa; no es una lista de configuración.", "Un SLA define niveles de servicio, como tiempos de respuesta, entre un proveedor y un cliente; no enumera pasos de configuración.", null]],
  "ap75": ["Antes de un cambio planificado en el firewall, el comité asesor de cambios pregunta qué pasará si el cambio rompe producción. ¿Qué parte de la solicitud responde esto?", ["El plan de reversión (rollback)", "La etiqueta de activo", "La aceptación del usuario final", "La orden de compra"], "Un plan de reversión explica cómo volver al estado de funcionamiento anterior si el cambio falla.", [null, "Una etiqueta de activo identifica un equipo; no describe cómo deshacer un cambio fallido.", "La aceptación del usuario final confirma después que el cambio funciona para los usuarios; no explica qué pasa si rompe producción.", "Una orden de compra se refiere a adquirir bienes o servicios; no tiene nada que ver con recuperarse de un cambio fallido."]],
  "ap76": ["Un trabajo de respaldo ejecuta un respaldo completo el domingo y respaldos diferenciales los demás días. El servidor falla el jueves por la mañana. ¿Qué se debe restaurar?", ["Solo el diferencial del miércoles", "El completo del domingo y todos los diferenciales desde entonces", "El completo del domingo y el diferencial del miércoles", "Solo el completo del domingo"], "Un diferencial contiene todos los cambios desde el último completo, así que se necesita el completo más el diferencial más reciente.", ["Un diferencial solo contiene los cambios desde el último respaldo completo, así que no puede restaurarse sin el completo del domingo.", "Cada diferencial ya incluye todos los cambios desde el completo, así que los diferenciales anteriores no son necesarios; ese es el método incremental.", null, "Restaurar solo el completo del domingo perdería todos los cambios hechos de lunes a miércoles."]],
  "ap77": ["Una empresa quiere seguir la regla de respaldo 3-2-1. ¿Qué configuración la cumple?", ["Tres copias de los datos en dos tipos de medios, con una copia fuera del sitio", "Tres respaldos al día conservados durante dos semanas, uno por servidor", "Tres servidores en dos racks con un UPS", "Un respaldo completo, dos incrementales y tres diferenciales"], "3-2-1 significa tres copias, dos medios diferentes y una fuera del sitio.", [null, "La frecuencia y el tiempo de retención son configuraciones aparte; no garantizan dos tipos de medios ni una copia fuera del sitio.", "La cantidad de servidores y racks describe redundancia de hardware, no copias de respaldo; un UPS es protección eléctrica, no un respaldo.", "Esto describe una mezcla de tipos de respaldo, no tres copias en dos medios con una fuera del sitio."]],
  "ap78": ["Los respaldos se han ejecutado cada noche durante un año, pero nadie sabe si funcionan. ¿Qué debe hacer el equipo?", ["Cambiar a respaldos incrementales", "Comprar más almacenamiento de respaldo", "Realizar pruebas de restauración periódicas", "Eliminar los respaldos más antiguos"], "Solo una prueba de restauración demuestra que los respaldos se pueden usar y cumplen los objetivos de tiempo de recuperación.", ["Cambiar el tipo de respaldo no demuestra que los respaldos existentes puedan restaurarse.", "Más almacenamiento conserva más respaldos, pero no demuestra que alguno realmente funcione.", null, "Eliminar los respaldos antiguos reduce las opciones de recuperación y tampoco verifica los restantes."]],
  "ap79": ["Antes de reemplazar la RAM de una PC de escritorio, ¿qué debe hacer un técnico para evitar daños electrostáticos?", ["Usar solo guantes de hule", "Dejar la PC conectada y encendida", "Usar una aspiradora para limpiar las ranuras", "Usar una pulsera ESD conectada a tierra y un tapete ESD"], "Una pulsera y un tapete ESD igualan la carga para que la estática no se descargue en los componentes. Hay que desconectar la PC antes de trabajar dentro de ella.", ["Los guantes de hule no drenan la carga estática a tierra de forma segura, así que no ofrecen protección ESD adecuada.", "Trabajar dentro de una PC conectada y encendida implica riesgo de descarga eléctrica y de daño a los componentes.", "Una aspiradora puede generar carga estática y dañar los componentes; lo habitual es usar aire comprimido.", null]],
  "ap80": ["Un técnico necesita saber cómo manipular y desechar de forma segura un cartucho de tóner que se derramó. ¿Dónde debe buscar?", ["La hoja de datos de seguridad (SDS) del producto", "La configuración IP de la impresora", "El acuerdo de nivel de servicio con el proveedor de la impresora", "El EULA"], "La SDS enumera los peligros, la manipulación, la limpieza de derrames y las instrucciones de desecho de un producto.", [null, "La configuración IP de la impresora cubre la red; no tiene información sobre cómo manipular tóner peligroso.", "Un SLA define niveles de servicio y tiempos de respuesta del proveedor; no incluye guías de manipulación ni desecho de materiales.", "El EULA cubre los términos de licencia del software; no describe cómo manejar derrames químicos."]],
  "ap81": ["Una oficina tiene con frecuencia breves parpadeos de energía que reinician las PC y han dañado la base de datos de un servidor. ¿Qué debe instalarse?", ["Solo un supresor de picos", "Un switch KVM", "Un sistema de alimentación ininterrumpida (UPS)", "Un segundo monitor"], "Un UPS proporciona energía de batería durante cortes breves y permite un apagado ordenado. Un supresor de picos no suministra energía.", ["Un supresor de picos solo absorbe picos de voltaje; no proporciona energía durante parpadeos o cortes.", "Un switch KVM permite que un teclado, monitor y mouse controlen varias computadoras; no suministra energía.", null, "Un segundo monitor agrega espacio de pantalla y no tiene nada que ver con los problemas de energía."]],
  "ap82": ["Mientras repara una laptop, un técnico ve archivos que parecen ser contenido ilegal. ¿Qué debe hacer PRIMERO?", ["Eliminar los archivos y terminar la reparación", "Detenerse, dejar la evidencia intacta y seguir el proceso de incidentes notificando a la autoridad correspondiente", "Copiar los archivos a una memoria USB para después", "Contárselo a sus compañeros"], "Hay que preservar la evidencia, reportar según la política (a la gerencia o a las autoridades) y mantener la cadena de custodia. Eliminar o copiar daña la evidencia.", ["Eliminar los archivos destruye evidencia y podría ser ilegal en sí mismo; el técnico debe preservarla.", null, "Copiar los archivos a una USB altera la evidencia, rompe la cadena de custodia y podría implicar poseer contenido ilegal.", "Contárselo a los compañeros difunde información confidencial y no sigue el proceso de reporte adecuado."]],
  "ap83": ["Una empresa tiene una licencia para 25 instalaciones de una aplicación y la instaló en 40 PC. ¿Qué infringe esto?", ["El acuerdo de licencia del software (EULA)", "La política de uso aceptable del ISP", "El GDPR", "El acuerdo de nivel de servicio con la mesa de ayuda"], "El EULA define cuántas instalaciones o usuarios se permiten; excederlo es una infracción de licencia.", [null, "La política de uso aceptable de un ISP regula el uso de su servicio de internet, no la cantidad de instalaciones de un software.", "El GDPR regula el tratamiento de datos personales de personas en la UE; no trata sobre la cantidad de instalaciones de software.", "Un SLA con la mesa de ayuda define tiempos de respuesta del soporte; no controla cuántas copias de software se pueden instalar."]],
  "ap84": ["Un técnico está en sitio para arreglar una PC lenta y el cliente está visiblemente molesto por problemas repetidos. ¿Cuál es el MEJOR enfoque?", ["Explicar que no es su culpa y seguir adelante", "Discutir sobre quién causó el problema", "Publicarlo en redes sociales", "Escuchar sin interrumpir, reconocer la frustración y explicar los próximos pasos"], "La escucha activa, mantener la calma y establecer expectativas claras ayudan a calmar a un cliente difícil.", ["Desestimar la queja hace que el cliente se sienta ignorado y no resuelve su problema.", "Discutir sobre culpas empeora la situación y no es profesional.", "Publicar sobre un cliente en redes sociales no es profesional y podría revelar información confidencial.", null]],
  "ap85": ["Un técnico debe volver a asignar las mismas unidades de red en 300 PC con Windows cada vez que los usuarios inician sesión. ¿Qué tipo de script es el MÁS adecuado?", ["Un script de PowerShell (.ps1)", "Un script de Bash (.sh)", "Un archivo .dmg de macOS", "Un notebook de Python en el teléfono del técnico"], "PowerShell es nativo de Windows y es adecuado para scripts de inicio de sesión que asignan unidades. Los scripts de Bash son para shells de Linux y macOS.", [null, "Los scripts de Bash se ejecutan en shells de Linux y macOS; Windows no los ejecuta de forma nativa al iniciar sesión.", "Un archivo .dmg es una imagen de disco de macOS para instalar software; no es un script y no se ejecuta en Windows.", "Un notebook en el teléfono del técnico no puede ejecutarse automáticamente en 300 PC con Windows como script de inicio de sesión."]],
  "ap86": ["Un script descargado de un foro afirma que acelera Windows. ¿Cuál es el principal riesgo de ejecutarlo en PC de producción sin revisarlo?", ["Podría ser demasiado corto", "Podría introducir malware o cambiar configuraciones del sistema sin querer", "Cambiará cada PC a una distribución de teclado e idioma de pantalla incorrectos", "No puede ejecutarse sin Python"], "Los scripts no probados pueden traer malware, alterar configuraciones o bloquear sistemas. Primero hay que revisarlos y probarlos en un sandbox.", ["La longitud de un script no es un riesgo de seguridad; el peligro es lo que realmente hace el código sin revisar.", null, "Cambiar la distribución del teclado o el idioma es un efecto poco probable y menor en comparación con malware o configuraciones dañadas.", "Los scripts pueden escribirse en muchos lenguajes, como PowerShell o batch; no necesitar Python no es la preocupación."]],
  "ap87": ["Una mesa de ayuda necesita monitorear, parchear y dar soporte remoto a cientos de PC cliente desde una sola consola. ¿Qué tipo de herramienta es adecuada?", ["Monitoreo y administración remota (RMM)", "VNC en cada PC con una contraseña compartida", "Telnet", "Abrir los puertos RDP de cada PC hacia internet"], "Las plataformas RMM centralizan el monitoreo, los parches, los scripts y el control remoto. Exponer RDP o Telnet a internet no es seguro.", [null, "VNC en cada PC solo da control remoto, sin monitoreo ni parches centralizados, y una contraseña compartida es insegura.", "Telnet es un protocolo de terminal remota sin cifrar; no monitorea ni parchea PC.", "Exponer RDP a internet invita ataques de fuerza bruta y tampoco ofrece monitoreo ni parches centralizados."]],
  "ap88": ["Un administrador necesita acceso seguro por línea de comandos a un servidor Linux a través de la red. ¿Qué protocolo debe usar?", ["RDP", "SSH", "Telnet", "SPICE"], "SSH proporciona un shell remoto cifrado. Telnet envía todo, incluidas las contraseñas, en texto claro.", ["RDP ofrece un escritorio remoto gráfico principalmente para Windows; no es la herramienta estándar de línea de comandos segura para Linux.", null, "Telnet ofrece un shell remoto, pero envía todo, incluidas las contraseñas, en texto claro.", "SPICE es un protocolo de visualización remota para máquinas virtuales, no un protocolo de acceso seguro por línea de comandos."]],
  "ap89": ["Un empleado pega un contrato de un cliente en un chatbot de IA público y gratuito para resumirlo. ¿Cuál es la principal preocupación?", ["El resumen será demasiado corto", "Los chatbots no pueden leer contratos", "El proveedor del modelo público podría almacenar o usar los datos confidenciales", "El contrato se eliminará del servidor"], "Las herramientas de IA públicas pueden conservar y usar los datos enviados, lo que pone en riesgo la privacidad y la confidencialidad. La política de la empresa debe restringir esto.", ["La longitud del resumen es un tema de calidad, no la principal preocupación; el riesgo es exponer datos confidenciales.", "Los chatbots pueden leer y resumir contratos; la preocupación es a dónde van los datos, no la capacidad.", null, "Pegar texto en un chatbot no elimina el contrato del servidor de la empresa."]],
  "ap90": ["Un asistente de IA le da a un técnico un comando con un modificador que no existe. ¿Qué limitación de la IA es esta?", ["Sesgo", "Plagio", "Retención de datos", "Alucinación"], "Una alucinación es una respuesta segura pero falsa. Las respuestas de la IA deben verificarse antes de usarlas.", ["El sesgo es una desviación sistemática en las respuestas de la IA según sus datos de entrenamiento; un modificador inventado es una invención.", "El plagio es copiar el trabajo de otros sin dar crédito; inventar un modificador inexistente es un problema diferente.", "La retención de datos se refiere a cuánto tiempo conserva el proveedor los datos enviados; no explica un comando inventado.", null]],
  "x1": ["Un administrador de Windows Server está formateando un volumen de almacenamiento grande que alojará archivos de máquinas virtuales. Quiere un sistema de archivos de Microsoft diseñado para la integridad de los datos y la resiliencia, no para arrancar Windows. ¿Cuál debe elegir?", ["FAT32", "exFAT", "ReFS", "APFS"], "ReFS (Resilient File System) es el sistema de archivos de Microsoft diseñado para verificación de integridad y resiliencia en volúmenes de datos grandes, como el almacenamiento de VM. APFS es tentador porque también es moderno, pero es el sistema de archivos de Apple y Windows no lo usa de forma nativa.", ["FAT32 es un sistema de archivos heredado con un límite de 4 GB por archivo y sin funciones de integridad.", "exFAT está hecho para medios flash extraíbles, no para volúmenes de datos resilientes de servidor.", null, "APFS es el sistema de archivos de Apple y Windows Server no lo admite de forma nativa."]],
  "x2": ["Un usuario de Linux formateó una memoria USB como ext4 para que coincidiera con su laptop Ubuntu. Al conectarla a una PC con Windows 11, el Explorador de archivos ofrece formatearla en lugar de mostrar los archivos. ¿Cuál es la causa MÁS probable?", ["Windows no puede leer ext4 sin software adicional", "Windows 11 no admite exFAT en memorias USB", "La memoria tiene un volumen NTFS que Linux bloqueó", "Las memorias USB no pueden usar una tabla de particiones GPT"], "ext4 es un sistema de archivos nativo de Linux que Windows no lee de fábrica, así que Windows trata el volumen como sin formato. Culpar a exFAT es incorrecto porque la memoria es ext4, y de todos modos Windows lee exFAT de forma nativa.", [null, "Windows 11 lee y escribe exFAT de forma nativa, y en cualquier caso la memoria es ext4.", "La memoria se formateó como ext4, no NTFS, y Linux no bloquea los volúmenes de esa forma.", "Las memorias USB pueden usar GPT, y el estilo de partición no haría que Windows ofreciera formatear un volumen legible."]],
  "x3": ["Un usuario de Mac está borrando un SSD externo en Utilidad de Discos. Solo se usará con Mac con una versión actual de macOS y debe admitir snapshots y cifrado nativo. ¿Qué formato es el MÁS adecuado?", ["exFAT", "FAT32", "NTFS", "APFS"], "APFS es el sistema de archivos moderno de Apple, optimizado para SSD y con soporte para snapshots y cifrado nativo. exFAT es la opción tentadora para unidades multiplataforma, pero no tiene esas funciones y no es necesario cuando solo se usarán Mac.", ["exFAT funciona en varias plataformas, pero no tiene los snapshots ni el cifrado nativo de APFS.", "FAT32 es un formato heredado con un límite de 4 GB por archivo y sin snapshots ni cifrado.", "macOS solo puede leer NTFS de forma predeterminada, así que no puede escribir en una unidad NTFS sin software adicional.", null]],
  "x4": ["La PC con Windows 10 Pro de un usuario cumple los requisitos de hardware de Windows 11. Quiere pasar a Windows 11 conservando sus aplicaciones instaladas, archivos y configuración. ¿Qué tipo de instalación debe usar el técnico?", ["Instalación limpia desde una memoria USB", "Actualización in situ", "Implementación de imagen mediante PXE", "Restablecer este equipo desde Configuración"], "Una actualización in situ instala la nueva versión de Windows sobre la anterior y conserva aplicaciones, archivos y configuración. Una instalación limpia es tentadora porque es muy confiable, pero borra las aplicaciones y la configuración existentes.", ["Una instalación limpia borra las aplicaciones y la configuración que el usuario quiere conservar.", null, "La implementación de imagen reemplaza todo el sistema con una imagen estándar en lugar de conservar la configuración del usuario.", "Restablecer este equipo reinstala la misma versión de Windows y quita aplicaciones; no actualiza a Windows 11."]],
  "x5": ["Durante una instalación limpia de Windows en un servidor con una controladora RAID por hardware, el instalador no muestra discos donde instalar. El arreglo está sano en la utilidad de configuración de la propia controladora. ¿Qué debe hacer el técnico?", ["Convertir los discos de MBR a GPT con diskpart", "Crear una nueva memoria de instalación y reiniciar el instalador", "Cargar el driver de almacenamiento de la controladora RAID durante la instalación", "Cambiar el método de arranque de USB a PXE"], "El instalador de Windows solo ve los discos para los que tiene driver; cargar el driver de almacenamiento del fabricante con la opción Cargar controlador expone el arreglo. Convertir a GPT es tentador, pero el estilo de partición no importa cuando el instalador ni siquiera puede ver el disco.", ["El estilo de partición no importa cuando el instalador no puede detectar el disco en absoluto.", "El medio de instalación funciona; el problema es que no tiene driver para la controladora RAID.", null, "PXE solo cambia desde dónde se carga el instalador; seguiría faltando el driver de almacenamiento."]],
  "x6": ["Una PC con Windows 11 tiene daños persistentes en el sistema. sfc /scannow y DISM /RestoreHealth no lo corrigieron, y el usuario quiere conservar las aplicaciones y archivos instalados. ¿Cuál es el MEJOR siguiente paso?", ["Ejecutar una instalación de reparación in situ de la misma versión", "Hacer una instalación limpia y restaurar los archivos desde un respaldo", "Restablecer la PC con la opción Quitar todo", "Revertir el driver más reciente en el Administrador de dispositivos"], "Una instalación de reparación reinstala la misma versión de Windows sobre sí misma, reemplazando los archivos del sistema y conservando aplicaciones y datos. Una instalación limpia también corregiría el daño, pero elimina las aplicaciones que el usuario quiere conservar.", [null, "Una instalación limpia corrige el daño, pero elimina todas las aplicaciones instaladas, que el usuario quiere conservar.", "Quitar todo borra las aplicaciones y los archivos personales, mucho más de lo que el usuario quiere.", "Revertir un driver no reparará un daño en todo el sistema que sfc y DISM no pudieron corregir."]],
  "x7": ["Un usuario con Windows 11 Home quiere conectarse a esta PC de su casa desde el trabajo usando el cliente integrado de Remote Desktop. ¿Qué se requiere en la PC de la casa?", ["Habilitar Escritorio remoto en Configuración > Sistema", "Permitir TCP 3389 en Windows Firewall", "Instalar la aplicación Remote Desktop desde la Store", "Actualizarla a Windows 11 Pro o superior"], "Las ediciones Home pueden conectarse hacia afuera con Remote Desktop, pero no pueden funcionar como host de Remote Desktop; se necesita Pro, Enterprise o Education. Habilitarlo en Configuración es tentador, pero esa opción no está disponible en Home.", ["La configuración de host de Escritorio remoto no está disponible en Windows 11 Home.", "Abrir el puerto no sirve de nada porque Home no tiene un servicio de host de Remote Desktop que acepte conexiones.", "La aplicación cliente permite que una PC se conecte hacia afuera; no permite que una PC Home acepte sesiones entrantes.", null]],
  "x8": ["Un sitio web interno aparece como no confiable. TI indica que el certificado de la CA raíz de la empresa debe agregarse al almacén Entidades de certificación raíz de confianza del usuario. ¿Qué herramienta debe abrir el técnico?", ["lusrmgr.msc", "certmgr.msc", "gpedit.msc", "devmgmt.msc"], "certmgr.msc es el complemento Administrador de certificados para los almacenes de certificados del usuario actual, incluido Entidades de certificación raíz de confianza. gpedit.msc puede distribuir certificados mediante directivas, pero no es la herramienta para importar uno directamente en esta PC.", ["lusrmgr.msc administra usuarios y grupos locales, no almacenes de certificados.", null, "gpedit.msc edita la directiva local y no es la herramienta para importar un certificado a un almacén.", "devmgmt.msc administra dispositivos de hardware y drivers, no certificados."]],
  "x9": ["Un técnico debe registrar los contadores de CPU, memoria y cola de disco de un servidor durante 24 horas para demostrar un cuello de botella y revisar los datos después. ¿Qué herramienta debe usar?", ["La pestaña Rendimiento del Administrador de tareas", "Monitor de recursos", "Monitor de rendimiento", "Monitor de confiabilidad"], "El Monitor de rendimiento puede registrar contadores elegidos a lo largo del tiempo con un conjunto de recopiladores de datos y reproducirlos después. El Monitor de recursos es tentador porque muestra el uso detallado en vivo, pero no registra contadores durante un periodo largo.", ["El Administrador de tareas solo muestra gráficas en vivo y no puede registrar contadores elegidos durante 24 horas.", "El Monitor de recursos muestra el uso detallado en tiempo real, pero no registra contadores durante periodos largos.", null, "El Monitor de confiabilidad registra bloqueos y cambios a lo largo de los días, no contadores de rendimiento."]],
  "x10": ["Desde Windows, un técnico quiere que la PC arranque en Modo seguro con funciones de red en cada reinicio hasta que lo desactive. ¿Qué herramienta configura esto?", ["Configuración del sistema (msconfig)", "Editor del Registro (regedit)", "Servicios (services.msc)", "Liberador de espacio en disco (cleanmgr)"], "La pestaña Arranque de Configuración del sistema tiene una opción Arranque a prueba de errores con la opción Red, que permanece activa hasta que se desmarca. El Editor del Registro es tentador porque controla muchas configuraciones, pero no es la herramienta admitida para elegir un modo de arranque.", [null, "Editar el registro a mano es riesgoso y no es la forma admitida de elegir un modo de arranque.", "services.msc inicia y detiene servicios; no tiene una configuración de modo de arranque.", "El Liberador de espacio en disco elimina archivos temporales e innecesarios y no tiene nada que ver con las opciones de arranque."]],
  "x11": ["Los archivos de una unidad de datos NTFS secundaria (D:) a veces se vuelven ilegibles, y Windows informa que la unidad tiene errores en el sistema de archivos. ¿Qué comando debe ejecutar el técnico para revisarlos y corregirlos?", ["format D: /q", "diskpart, luego clean", "sfc /scannow", "chkdsk D: /f"], "chkdsk con /f revisa el sistema de archivos del volumen y corrige los errores que encuentra. sfc /scannow es tentador porque repara cosas, pero solo repara archivos protegidos del sistema de Windows, no el sistema de archivos de un volumen de datos.", ["Formatear borra el volumen, destruyendo los archivos en lugar de reparar el sistema de archivos.", "El comando clean de diskpart borra la información de particiones del disco, lo que destruye los datos.", "sfc repara archivos protegidos del sistema de Windows, no errores del sistema de archivos en una unidad de datos.", null]],
  "x12": ["Un usuario dice que una nueva configuración de Group Policy no se está aplicando. El técnico quiere ver qué objetos de directiva de grupo (GPO) se aplicaron al usuario y al equipo. ¿Qué comando debe ejecutar?", ["gpupdate /force", "gpresult /r", "whoami /groups", "net user %username%"], "gpresult /r muestra el conjunto resultante de directivas (RSoP), con los GPO aplicados al equipo y al usuario. gpupdate /force es tentador, pero solo vuelve a aplicar las directivas y no muestra qué GPO se aplicaron.", ["gpupdate /force vuelve a aplicar las directivas, pero no informa qué GPO se aplicaron.", null, "whoami /groups muestra las membresías de grupo del usuario, no las directivas aplicadas.", "net user muestra detalles de la cuenta como la configuración de contraseña, no los resultados de Group Policy."]],
  "x13": ["Un técnico sospecha que un programa en una PC con Windows mantiene abierta una conexión hacia un servidor remoto desconocido. ¿Qué comando enumera las conexiones activas junto con los ID de proceso propietarios?", ["tracert", "nslookup", "netstat -ano", "pathping"], "netstat -ano enumera todas las conexiones y puertos en escucha con direcciones numéricas y el PID propietario de cada una. pathping es tentador como herramienta de red, pero solo mide la ruta y la pérdida de paquetes hacia un destino.", ["tracert muestra los saltos hacia un destino, no las conexiones abiertas en esta PC.", "nslookup consulta registros DNS y no enumera las conexiones activas.", null, "pathping mide la ruta y la pérdida de paquetes hacia un host; no enumera conexiones locales ni PID."]],
  "x14": ["Un administrador de Linux agrega un disco de datos. Se monta correctamente con el comando mount, pero desaparece después de cada reinicio. ¿Qué archivo debe editarse para que se monte automáticamente?", ["/etc/fstab", "/etc/hosts", "/etc/resolv.conf", "/etc/passwd"], "/etc/fstab enumera los sistemas de archivos y sus puntos de montaje para montarlos al arrancar. /etc/resolv.conf es tentador por ser otro archivo de configuración básico, pero solo define los resolvers DNS y no tiene nada que ver con los discos.", [null, "/etc/hosts asigna nombres de host a direcciones IP y no controla el montaje.", "/etc/resolv.conf define los resolvers DNS y no tiene nada que ver con los discos.", "/etc/passwd almacena información de cuentas de usuario, no puntos de montaje."]],
  "x15": ["En una estación de trabajo Ubuntu, un técnico necesita el ID de proceso de un proceso en segundo plano colgado llamado reportd para poder detenerlo. ¿Qué comando lo encuentra?", ["df -h | grep reportd", "man reportd", "find / -name reportd", "ps aux | grep reportd"], "ps aux enumera los procesos en ejecución con sus PID, y grep filtra por el nombre. find es tentador porque localiza cosas, pero busca archivos en el sistema de archivos, no procesos en ejecución.", ["df -h informa el uso de espacio en disco por sistema de archivos, no los procesos en ejecución.", "man muestra una página del manual; no informa si el proceso está en ejecución ni su PID.", "find busca archivos en el disco, no procesos que se ejecutan en memoria.", null]],
  "x16": ["Un usuario de Mac descargó un archivo .dmg que contiene una aplicación. ¿Cuál es la forma habitual de instalar la aplicación?", ["Montar el .dmg y luego ejecutar su contenido con sudo desde Terminal", "Abrir el .dmg y arrastrar la aplicación a la carpeta Aplicaciones", "Renombrar el .dmg a .pkg y hacer doble clic", "Copiar el propio archivo .dmg a la carpeta Aplicaciones"], "Un .dmg es una imagen de disco; al abrirlo se monta, y la .app que contiene se arrastra a Aplicaciones para instalarla. Copiar el .dmg es tentador, pero eso solo guarda la imagen de disco y no instala la aplicación.", ["Un .dmg normalmente contiene una aplicación para arrastrar a Aplicaciones; ejecutar cosas con sudo es innecesario y riesgoso.", null, "Renombrar el archivo no cambia su formato; un .dmg no es un paquete instalador.", "Copiar el .dmg solo guarda la imagen de disco; la aplicación nunca se instala."]],
  "x17": ["Una MacBook con archivos de clientes necesita cifrado de disco completo para que los datos no puedan leerse si roban la laptop. ¿Qué función integrada debe activarse?", ["Acceso a Llaveros (Keychain Access)", "Time Machine", "FileVault", "Gatekeeper"], "FileVault cifra todo el disco de arranque de una Mac. Acceso a Llaveros es tentador porque protege secretos, pero solo almacena contraseñas, claves y certificados, no el disco completo.", ["Acceso a Llaveros almacena contraseñas, claves y certificados; no ofrece cifrado de disco completo.", "Time Machine hace respaldos; no cifra el disco de arranque contra robos.", null, "Gatekeeper verifica que las aplicaciones provengan de desarrolladores de confianza; no cifra datos."]],
  "x18": ["Una clínica todavía tiene una PC con una versión de sistema operativo que el fabricante declaró en fin de vida (end-of-life). ¿Cuál es el principal riesgo de seguir usándola?", ["Ya no recibe parches de seguridad, así que las nuevas fallas quedan abiertas", "Dejará de arrancar en la fecha de fin de vida del fabricante", "Las licencias del software instalado dejan de ser válidas", "Ya no puede unirse a un grupo de trabajo ni a un dominio"], "Después del fin de vida, el fabricante deja de publicar actualizaciones de seguridad, así que las vulnerabilidades recién descubiertas quedan sin parche. La idea de que deja de arrancar es tentadora pero falsa: los sistemas EOL siguen funcionando, y justamente por eso persiste el riesgo.", [null, "Los sistemas en fin de vida siguen arrancando; el problema es que dejan de recibir correcciones.", "Las licencias existentes siguen siendo válidas después del fin de vida; la verdadera preocupación es la seguridad.", "Un sistema EOL todavía puede unirse a un grupo de trabajo o a un dominio; el riesgo es quedarse sin parches."]],
  "x19": ["En una PC compartida con Windows Pro, un usuario quiere cifrar una sola carpeta para que otras personas que inician sesión en la misma PC no puedan abrirla. No se requiere cifrar toda la unidad. ¿Qué función es adecuada?", ["Cifrado de unidad BitLocker", "BitLocker To Go", "Atributo de compresión NTFS", "EFS"], "EFS (Encrypting File System) cifra archivos y carpetas individuales ligados a la cuenta de un usuario, así que otros usuarios de la misma PC no pueden abrirlos. BitLocker es tentador, pero una vez desbloqueado el volumen no detiene a otros usuarios con sesión iniciada que tengan acceso NTFS.", ["BitLocker protege todo el volumen contra el acceso sin conexión, pero una vez desbloqueado otros usuarios con acceso NTFS pueden leer los archivos.", "BitLocker To Go cifra unidades extraíbles, no una carpeta del disco interno.", "La compresión ahorra espacio; no cifra ni impide que otros usuarios lean los archivos.", null]],
  "x20": ["Una empresa quiere que los empleados inicien sesión en sus laptops Windows sin escribir contraseña, usando el lector de huellas integrado o la cámara facial IR. ¿Qué función debe habilitar?", ["Windows Hello", "Administrador de credenciales", "Control de cuentas de usuario", "Microsoft Defender SmartScreen"], "Windows Hello ofrece inicio de sesión biométrico y con PIN en Windows. El Administrador de credenciales es tentador porque se relaciona con el inicio de sesión, pero solo almacena credenciales guardadas de sitios y recursos de red.", [null, "El Administrador de credenciales almacena credenciales guardadas de sitios y recursos; no hace inicio de sesión biométrico.", "UAC solicita la elevación; no ofrece inicio de sesión sin contraseña.", "SmartScreen advierte sobre sitios y descargas inseguros; no tiene función de inicio de sesión."]],
  "x21": ["Un administrador otorga al grupo HR el permiso Modificar en la carpeta D:\\HR. Una nueva subcarpeta creada dentro muestra la misma entrada para HR, pero sus casillas aparecen en gris. ¿Por qué?", ["El creador de la subcarpeta bloqueó los permisos", "Los permisos se heredan de la carpeta principal", "Los permisos de recurso compartido anulan NTFS en las subcarpetas", "UAC bloquea la edición de permisos en carpetas nuevas"], "Las entradas de permisos en gris son heredadas de la carpeta principal; hay que cambiarlas en la principal o deshabilitar la herencia en la subcarpeta. Culpar a los permisos de recurso compartido es tentador, pero estos nunca aparecen en la pestaña Seguridad de NTFS.", ["Los creadores pueden ser propietarios de una carpeta, pero la propiedad no pone las entradas en gris; la herencia sí.", null, "Los permisos de recurso compartido nunca aparecen en la pestaña Seguridad de NTFS, así que no pueden poner en gris estas entradas.", "UAC puede pedir elevación, pero no pone en gris entradas de permisos individuales."]],
  "x22": ["Un access point SOHO antiguo está configurado con WPA2 y TKIP. Todos los dispositivos cliente admiten AES. ¿Qué cambio mejora la seguridad inalámbrica sin hardware nuevo?", ["Cambiar la seguridad a WEP para los clientes antiguos", "Ocultar el SSID de las transmisiones", "Cambiar el cifrado a AES (CCMP)", "Habilitar WPS para facilitar la conexión"], "TKIP es un cifrado heredado y más débil; WPA2 con AES (CCMP) es la configuración segura y todos los clientes lo admiten. Ocultar el SSID es tentador, pero el SSID sigue visible en el tráfico de los clientes y no hace nada contra el cifrado débil.", ["WEP está comprometido y es mucho más débil incluso que WPA2 con TKIP.", "Ocultar el SSID no es seguridad real, ya que el nombre sigue apareciendo en el tráfico de los clientes.", null, "WPS tiene debilidades conocidas en el PIN y debe deshabilitarse, no habilitarse."]],
  "x23": ["¿Por qué WPA3-Personal es más resistente que WPA2-Personal ante un atacante que captura el handshake e intenta adivinar la frase de acceso sin conexión?", ["Autentica a cada usuario mediante un servidor RADIUS", "Cifra cada trama con TKIP en lugar de AES", "Oculta el SSID para que los atacantes no puedan capturarlo", "Usa SAE en lugar del handshake PSK de WPA2"], "WPA3-Personal usa Simultaneous Authentication of Equals (SAE), que impide los ataques de diccionario sin conexión contra un handshake capturado. RADIUS es tentador, pero eso corresponde al modo Enterprise, no a Personal, que sigue usando una frase de acceso compartida.", ["RADIUS lo usa WPA3-Enterprise, no WPA3-Personal, que sigue usando una frase de acceso.", "TKIP es un cifrado heredado que WPA3 no usa en absoluto.", "Ocultar el SSID no impide capturar el handshake y no forma parte de WPA3.", null]],
  "x24": ["Alguien accedió a las cuentas bancarias y de correo de un empleado aunque usa contraseñas fuertes y únicas. Un análisis encuentra un programa oculto que registra cada pulsación de tecla y envía los datos hacia afuera. ¿Qué tipo de malware es?", ["Keylogger", "Adware", "Ransomware", "Virus del sector de arranque"], "Un keylogger captura las pulsaciones de teclas, incluidas las contraseñas, y las envía al atacante. El adware es tentador porque también es software no deseado, pero muestra anuncios en lugar de robar credenciales escritas.", [null, "El adware muestra anuncios no deseados; no captura las contraseñas escritas.", "El ransomware cifra archivos y exige un pago; no registra pulsaciones de teclas en silencio.", "Un virus del sector de arranque infecta el código de inicio; no está diseñado para registrar pulsaciones de teclas."]],
  "x25": ["EDR alerta que Word inició PowerShell, que ejecutó comandos codificados completamente en memoria. El antivirus no encontró ningún archivo malicioso en disco. ¿Qué tipo de amenaza es la MÁS probable?", ["Virus del sector de arranque", "Malware sin archivos (fileless)", "Adware", "Rootkit"], "El malware sin archivos vive en memoria y abusa de herramientas integradas como PowerShell, dejando poco o nada en disco para los análisis por firmas. Rootkit es tentador porque ambos son sigilosos, pero un rootkit se oculta modificando el sistema operativo en lugar de ejecutarse desde un script en memoria iniciado por una macro.", ["Un virus del sector de arranque vive en el código de inicio en disco, lo que no coincide con actividad de PowerShell solo en memoria.", null, "El adware muestra anuncios no deseados y normalmente no ejecuta PowerShell codificado desde una macro.", "Un rootkit se oculta modificando el sistema operativo, no ejecutando comandos de script en memoria desde un documento."]],
  "x26": ["Una empresa quiere detectar comportamientos sospechosos en las laptops, registrar la actividad de procesos para investigaciones y aislar de la red una laptop infectada desde una consola central. ¿Qué herramienta es adecuada?", ["Firewall basado en host", "Gateway de seguridad de correo", "EDR", "Antivirus solo por firmas"], "La detección y respuesta de endpoints (EDR) monitorea el comportamiento de los endpoints, registra la actividad para investigaciones y puede aislar hosts de forma remota. El antivirus solo por firmas es tentador, pero compara archivos conocidos y no ofrece registro de comportamiento ni aislamiento remoto.", ["Un firewall de host filtra el tráfico, pero no registra la actividad de procesos para investigaciones.", "Un gateway de correo filtra el correo antes de que llegue a los usuarios; no monitorea los endpoints.", null, "El antivirus basado en firmas compara archivos conocidos y no tiene registro de comportamiento ni aislamiento remoto."]],
  "x27": ["Una usuaria sospecha que alguien instaló en secreto una aplicación en su teléfono que informa su ubicación, mensajes y llamadas a otra persona. ¿A qué categoría de software malicioso corresponde?", ["Adware", "Cryptominer", "Ransomware", "Stalkerware"], "El stalkerware es software de vigilancia encubierta que envía la ubicación y las comunicaciones de la víctima a otra persona. Un cryptominer es tentador porque también se ejecuta oculto, pero usa el dispositivo para minar criptomonedas y no rastrea al usuario.", ["El adware muestra anuncios; no informa en secreto la ubicación y los mensajes a una persona.", "Un cryptominer usa la CPU del dispositivo para minar criptomonedas y no rastrea al usuario.", "El ransomware bloquea los datos a cambio de un pago y se da a conocer, a diferencia de la vigilancia encubierta.", null]],
  "x28": ["El director financiero recibe un correo que menciona por nombre una adquisición real pendiente y pide con urgencia una transferencia bancaria confidencial para cerrar el trato. ¿Qué tipo de ataque es?", ["Whaling", "Vishing", "Smishing", "Tailgating"], "El whaling es phishing dirigido a altos ejecutivos, con detalles que hacen creíble el mensaje. El vishing es tentador como otra variante de phishing, pero se hace por llamada de voz, no por correo.", [null, "El vishing usa llamadas de voz, pero este ataque llegó por correo.", "El smishing usa mensajes de texto, no correo.", "El tailgating es una técnica de ingreso físico, no un ataque basado en mensajes."]],
  "x29": ["Una persona que carga una pila de cajas sigue a un empleado a través de una puerta con control de credenciales sin pasar la suya. ¿Cómo se llama esto?", ["Shoulder surfing", "Tailgating", "Dumpster diving", "Evil twin"], "El tailgating es seguir a una persona autorizada a través de una entrada segura sin autenticarse. El shoulder surfing es tentador como otra técnica presencial, pero consiste en mirar la pantalla o el teclado de alguien para robar información.", ["El shoulder surfing consiste en mirar la pantalla o el teclado de alguien, no en entrar detrás de esa persona.", null, "El dumpster diving consiste en buscar información en la basura, no en entrar a un edificio.", "Un evil twin es un access point Wi-Fi falso, no una técnica de ingreso físico."]],
  "x30": ["Una empresa quiere donar discos duros funcionales a una escuela. Los datos no deben poder recuperarse, pero los discos deben seguir siendo utilizables. ¿Qué debe hacer el técnico?", ["Ejecutar un formateo rápido estándar en Windows", "Desmagnetizar cada disco con un borrador masivo", "Sobrescribir todos los sectores con una herramienta de borrado de discos", "Eliminar las particiones con diskpart"], "Sobrescribir cada sector con una herramienta de borrado elimina los datos y deja el disco reutilizable. La desmagnetización es tentadora porque borra los datos magnéticos, pero también destruye la información servo y deja inutilizable un disco duro.", ["Un formateo rápido deja la mayoría de los datos en su lugar, así que pueden recuperarse con herramientas comunes.", "La desmagnetización borra los datos magnéticos, pero también deja inutilizable un disco duro.", null, "Eliminar particiones deja los datos en los platos, donde las herramientas de recuperación pueden encontrarlos."]],
  "x31": ["Un atacante publica en un foro web de la empresa un comentario que contiene un script. Luego el script se ejecuta en el navegador de cada visitante que ve el comentario. ¿Qué ataque es este?", ["Inyección SQL", "Ataque on-path", "Exploit de día cero", "XSS"], "El cross-site scripting (XSS) inyecta un script en un sitio para que se ejecute en los navegadores de otros usuarios. La inyección SQL es tentadora porque ambas abusan de campos de entrada, pero la inyección SQL ataca las consultas a la base de datos del sitio, no los navegadores de los visitantes.", ["La inyección SQL ataca las consultas a la base de datos del sitio, no scripts en los navegadores de los visitantes.", "Un ataque on-path intercepta el tráfico entre dos partes; no almacena scripts en un sitio.", "Un día cero es una falla desconocida sin parche, no el nombre de esta técnica de inyección de scripts.", null]],
  "x32": ["Un técnico verificó síntomas de malware en una PC con Windows y la puso en cuarentena aislándola de la red. Según el procedimiento de eliminación de malware de CompTIA, ¿cuál es el siguiente paso?", ["Deshabilitar Restaurar sistema en Windows", "Actualizar el software antimalware y analizar", "Programar análisis y ejecutar actualizaciones del sistema operativo", "Educar al usuario final"], "El orden es: investigar y verificar síntomas, poner en cuarentena, deshabilitar Restaurar sistema, remediar (actualizar y analizar), programar análisis y actualizaciones, volver a habilitar Restaurar sistema y crear un punto de restauración, y educar al usuario. Actualizar y analizar es tentador, pero viene después de deshabilitar Restaurar sistema.", [null, "Actualizar y analizar es el paso de remediación, que viene después de deshabilitar Restaurar sistema.", "Programar análisis y actualizaciones viene después de eliminar el malware.", "Educar al usuario es el último paso del procedimiento, no el tercero."]],
  "x33": ["Una auditoría encuentra que los empleados suelen dejar sus PC desbloqueadas en áreas abiertas. ¿Qué medida de hardening aborda esto directamente?", ["Deshabilitar la cuenta Invitado integrada en todas las PC", "Configurar un bloqueo de pantalla temporizado que exija iniciar sesión", "Exigir que las contraseñas expiren cada 90 días", "Desactivar AutoPlay para todos los medios extraíbles"], "Un protector de pantalla o bloqueo por inactividad que exija iniciar sesión protege las PC desatendidas. Deshabilitar la cuenta Invitado es tentador como medida de hardening, pero no protege una sesión que ya está iniciada y abierta.", ["Deshabilitar Invitado es un buen hardening, pero no protege una sesión que ya está abierta.", null, "La expiración de contraseñas cambia la frecuencia con que se cambian, no lo que pasa en una PC abierta y desatendida.", "Deshabilitar AutoPlay impide el inicio automático de USB; no bloquea una pantalla desatendida."]],
  "x34": ["Durante la revisión de un router doméstico, un técnico ve que un dispositivo de la LAN abrió puertos entrantes en el router sin que nadie los configurara. ¿Qué configuración debe deshabilitarse?", ["WPS", "La red de invitados", "UPnP", "Reservas DHCP"], "UPnP permite que los dispositivos de la LAN pidan al router que abra puertos automáticamente, algo de lo que el malware puede abusar. WPS es tentador porque también suele deshabilitarse, pero WPS sirve para unirse al Wi-Fi con un PIN o botón y no abre puertos.", ["WPS se usa para unirse al Wi-Fi con un PIN o botón; no abre puertos entrantes.", "La red de invitados aísla a los visitantes; no permite que los dispositivos de la LAN abran puertos del router.", null, "Las reservas DHCP fijan la dirección IP de un dispositivo; no abren puertos en el router."]],
  "x35": ["Una oficina pequeña quiere que los visitantes tengan acceso a internet por Wi-Fi sin poder llegar a las PC, impresoras ni recursos compartidos de la oficina. ¿Qué debe configurar el técnico?", ["Compartir la frase de acceso del Wi-Fi principal con los invitados", "Activar el filtrado MAC en el SSID principal", "Crear reservas DHCP para los visitantes", "Habilitar la red de invitados aislada del router"], "Una red de invitados da acceso a internet a los visitantes y los separa de la LAN interna. El filtrado MAC es tentador, pero solo controla qué dispositivos pueden unirse y seguiría poniendo a los visitantes en la misma red que los sistemas de la oficina.", ["Compartir la frase de acceso principal pone a los visitantes en la misma red que los sistemas de la oficina.", "El filtrado MAC solo controla quién puede unirse; los visitantes igual llegarían a los dispositivos de la oficina.", "Las reservas DHCP asignan direcciones fijas; no separan a los visitantes de la LAN.", null]],
  "x36": ["Un usuario cree que la navegación privada (incógnito) oculta todo lo que hace de la red de la empresa. ¿Qué hace realmente la navegación privada?", ["Deja de guardar el historial local y las cookies al cerrar la ventana", "Cifra el tráfico para que la red de la oficina no vea qué sitios se cargan", "Oculta la dirección IP del dispositivo a todos los sitios web", "Bloquea todas las descargas de malware durante la sesión"], "La navegación privada solo evita conservar el historial local, las cookies y los datos de formularios después de la sesión; la red, el proxy y los sitios aún pueden ver el tráfico. Cifrar el tráfico frente a la red es tentador, pero eso describe una VPN, no la navegación privada.", [null, "La navegación privada no cifra el tráfico; esa es la función de HTTPS o de una VPN.", "Los sitios web siguen viendo la dirección IP pública del dispositivo en la navegación privada.", "La navegación privada no incluye análisis de malware ni bloquea descargas."]],
  "x37": ["Windows muestra una advertencia de memoria baja en una PC con bastante RAM. El Administrador de tareas muestra que el uso de memoria de una aplicación de negocio sube constantemente durante horas hasta que aparece la advertencia, incluso sin nada más abierto. ¿Cuál es la MEJOR solución?", ["Ampliar el archivo de paginación y dar el problema por resuelto", "Actualizar o parchear la aplicación, que probablemente tiene una fuga de memoria", "Reemplazar el disco del sistema por un SSD más rápido", "Ejecutar chkdsk /f en el disco del sistema"], "La memoria que crece constantemente en un proceso hasta agotarse es la señal clásica de una fuga de memoria, así que la aplicación necesita una corrección o actualización. Un archivo de paginación más grande es tentador, pero solo retrasa la advertencia mientras la fuga sigue creciendo.", ["Un archivo de paginación más grande solo retrasa la advertencia mientras la aplicación con la fuga sigue usando más memoria.", null, "Un disco más rápido no impide que una aplicación use cada vez más memoria.", "chkdsk repara errores del sistema de archivos y no tiene nada que ver con el consumo de memoria."]],
  "x38": ["Después de que un usuario instaló una utilidad gratuita del sistema, varias aplicaciones dejaron de funcionar, y desinstalar la utilidad no ayudó. Existe un punto de restauración anterior a la instalación, y los documentos del usuario deben conservarse. ¿Qué debe hacer el técnico?", ["Restablecer este equipo con la opción Quitar todo", "Reinstalar la imagen corporativa en la PC", "Usar Restaurar sistema al punto anterior a la instalación", "Ejecutar DISM para reparar el almacén de componentes"], "Restaurar sistema revierte archivos del sistema, drivers, configuración del registro y programas instalados al punto de restauración sin tocar los documentos personales. Reinstalar la imagen es tentador porque es exhaustivo, pero borra la PC cuando existe una solución menos drástica.", ["Quitar todo borra los documentos del usuario, que deben conservarse.", "Reinstalar la imagen borra la PC cuando hay disponible una reversión menos drástica.", null, "DISM repara el almacén de componentes de Windows; no deshace los cambios que hizo una utilidad de terceros."]],
  "x39": ["Una PC con Windows entra en un ciclo de Reparación automática y nunca llega al escritorio, y el Modo seguro tampoco carga. ¿Dónde puede el técnico ejecutar Reparación de inicio, Restaurar sistema o un Símbolo del sistema?", ["La pestaña Aplicaciones de arranque del Administrador de tareas", "El registro Sistema del Visor de eventos", "Configuración del sistema (msconfig)", "Entorno de recuperación de Windows"], "El Entorno de recuperación de Windows (WinRE) se ejecuta fuera del sistema operativo instalado y ofrece Reparación de inicio, Restaurar sistema, desinstalar actualizaciones y Símbolo del sistema. msconfig es tentador porque controla opciones de arranque, pero solo se ejecuta desde una sesión de Windows que funcione.", ["El Administrador de tareas se ejecuta dentro de Windows, que aquí no llega al escritorio.", "El Visor de eventos también necesita una sesión de Windows que funcione y no ofrece herramientas de reparación.", "msconfig solo se ejecuta desde una sesión de Windows que funcione.", null]],
  "x40": ["Una PC kiosco compartida ha tenido infecciones y bloqueos repetidos. Se han intentado sfc, DISM y reversiones de drivers durante varias semanas. La empresa tiene una imagen estándar y no se guardan datos de usuario localmente. ¿Cuál es la solución MÁS eficiente?", ["Reinstalar la imagen corporativa estándar", "Ejecutar otra ronda de reparaciones con sfc y DISM", "Volver a revertir cada driver actualizado recientemente", "Crear un nuevo perfil local para el usuario del kiosco"], "Cuando las reparaciones siguen fallando y no hay datos locales que perder, reinstalar la imagen devuelve la PC a un estado conocido y sano más rápido. Un perfil nuevo es tentador, pero no eliminaría el daño a nivel de sistema ni el malware persistente.", [null, "sfc y DISM ya fallaron repetidamente, así que es poco probable que otra ronda ayude.", "Las reversiones de drivers ya se intentaron y no abordan las infecciones repetidas.", "Un perfil nuevo no elimina el daño a nivel de sistema ni el malware."]],
  "x41": ["El teléfono de un usuario no completa pagos por contacto en las terminales de las tiendas, aunque otros teléfonos funcionan en las mismas terminales. El Wi-Fi y el Bluetooth funcionan normalmente. ¿Qué debe revisar el técnico PRIMERO?", ["Apagar y encender el Bluetooth e intentar de nuevo", "Confirmar que NFC esté activado y que una app de billetera sea la predeterminada", "Olvidar y volver a unirse a la red Wi-Fi de la tienda", "Restablecer el teléfono de fábrica para borrar la configuración"], "El pago por contacto usa NFC, así que NFC debe estar activado y una aplicación de pagos configurada como predeterminada. Reiniciar el Bluetooth es tentador porque también es inalámbrico de corto alcance, pero los pagos sin contacto no usan Bluetooth.", ["El pago sin contacto usa NFC, no Bluetooth.", null, "El pago por contacto no depende de la red Wi-Fi de la tienda.", "Un restablecimiento de fábrica es drástico y debe venir después de verificaciones simples como si NFC está activado."]],
  "x42": ["Una aplicación del teléfono de un usuario no se actualiza desde la tienda oficial, y el error indica que no hay suficiente espacio. ¿Qué debe hacer el técnico?", ["Restablecer el teléfono de fábrica y restaurar un respaldo", "Cerrar sesión en todas las cuentas del teléfono", "Liberar espacio de almacenamiento y reintentar la actualización", "Habilitar las opciones de desarrollador e instalarla por sideloading"], "El error apunta directamente al almacenamiento, así que la solución es quitar aplicaciones, contenido multimedia o caché que no se usen y reintentar. Un restablecimiento de fábrica es tentador como cura para todo, pero es drástico e innecesario ante una simple falta de espacio.", ["Un restablecimiento de fábrica es drástico e innecesario cuando el error solo dice que el almacenamiento está lleno.", "Cerrar sesión en las cuentas no libera espacio para la actualización.", null, "El sideloading evade las protecciones de la tienda y también necesita espacio libre."]],
  "x43": ["Un teléfono corporativo sigue activando alertas de límite de datos, aunque el usuario casi no lo usa. La configuración muestra que una aplicación de linterna instalada recientemente usa grandes cantidades de datos en segundo plano. ¿Qué debe hacer el técnico?", ["Contratar un plan de datos celulares más grande", "Desactivar las llamadas por Wi-Fi en la configuración", "Borrar la caché de todas las aplicaciones instaladas", "Quitar la aplicación de linterna y analizar el teléfono"], "Un tráfico de red alto e inesperado de una aplicación simple es señal de comportamiento malicioso o de spyware, así que hay que quitarla y analizar. Un plan de datos más grande es tentador porque detiene las alertas, pero ignora el probable robo de datos.", ["Un plan más grande oculta el síntoma mientras una aplicación probablemente maliciosa sigue enviando datos.", "Las llamadas por Wi-Fi no tienen nada que ver con los datos en segundo plano de una aplicación de linterna.", "Borrar la caché no impide que la aplicación envíe datos en segundo plano.", null]],
  "x44": ["Solo en una PC, al escribir la dirección del banco en cualquier navegador se abre un sitio parecido. La configuración del servidor DNS es correcta y otras PC de la misma red funcionan bien. ¿Qué debe revisar el técnico?", ["Inspeccionar el archivo hosts en busca de entradas alteradas", "Borrar la caché del navegador principal", "Reinstalar el navegador predeterminado del usuario", "Actualizar el driver del adaptador de red"], "Como todos los navegadores de esta PC están afectados mientras la configuración DNS es correcta, la causa probable es una redirección a nivel de sistema, como un archivo hosts modificado. Borrar la caché de un navegador es tentador, pero no explicaría que la redirección ocurra en todos los navegadores.", [null, "Borrar la caché de un navegador no explicaría que todos los navegadores de la PC sean redirigidos.", "El problema aparece en todos los navegadores, así que reinstalar uno no lo corregirá.", "Un problema de driver causaría falta de conectividad, no una redirección a un sitio parecido."]],
  "x45": ["El navegador de un usuario se volvió muy lento. El uso de CPU es alto solo mientras el navegador está abierto, y tiene muchas extensiones instaladas. ¿Qué debe intentar el técnico PRIMERO?", ["Vaciar la caché DNS con ipconfig /flushdns", "Deshabilitar todas las extensiones y volver a probar", "Reinstalar Windows con una instalación limpia", "Pedir al ISP que mejore la conexión"], "Las extensiones se ejecutan dentro del navegador y son una causa común de CPU alta y lentitud, así que deshabilitarlas aísla la causa. Vaciar el DNS es tentador, pero los problemas de DNS causan búsquedas fallidas, no CPU alta.", ["Vaciar el DNS corrige las búsquedas de nombres; no reduce el uso alto de CPU.", null, "Reinstalar Windows es drástico antes de probar verificaciones simples y específicas como las extensiones.", "Una conexión más rápida no reduce la carga de CPU dentro del navegador."]],
  "x46": ["Después de eliminar malware, una ventana emergente de estafa sigue apareciendo poco después de cada reinicio, aunque los análisis completos ahora salen limpios. ¿Dónde debe buscar el técnico el lanzador que quedó?", ["Los volúmenes de Administración de discos", "La lista de drivers del Administrador de dispositivos", "El Programador de tareas y las aplicaciones de arranque", "El almacén de usuario del Administrador de certificados"], "El malware a menudo deja una tarea programada o una entrada de inicio que vuelve a lanzar una ventana emergente en cada inicio de sesión. El Administrador de certificados es tentador porque el malware puede agregar certificados falsos, pero un certificado no inicia un programa al arrancar.", ["Administración de discos maneja particiones y volúmenes, no programas que se inician al arrancar.", "El Administrador de dispositivos enumera drivers de hardware, no las tareas o aplicaciones que inician al iniciar sesión.", null, "Un certificado no puede iniciar un programa; las tareas y entradas de inicio sí."]],
  "x47": ["Windows sigue mostrando notificaciones que afirman que se encontraron virus e instan al usuario a hacer clic. Provienen de un sitio web al que el usuario alguna vez permitió enviar notificaciones. ¿Cuál es la MEJOR solución?", ["Reinstalar el producto antivirus", "Pausar Windows Update durante una semana", "Desactivar todas las notificaciones de Seguridad de Windows en Configuración", "Revocar el permiso de notificaciones del sitio en el navegador"], "Las alertas provienen de un sitio con permiso de notificaciones, así que revocar ese permiso las detiene. Desactivar las notificaciones de Seguridad de Windows es tentador, pero ocultaría las alertas reales y dejaría funcionando las falsas.", ["Reinstalar el antivirus no revoca el permiso de un sitio web para enviar notificaciones.", "Pausar Windows Update no tiene nada que ver con las notificaciones de sitios web.", "Esto oculta las alertas de seguridad genuinas mientras continúan las notificaciones falsas del sitio.", null]],
  "x48": ["Una PC muestra pantallas azules en momentos aleatorios con un código de detención diferente cada vez, y Windows Memory Diagnostic reporta errores. ¿Qué debe hacer el técnico?", ["Reemplazar el módulo de RAM que falló la prueba", "Reinstalar el driver de gráficos del fabricante", "Ejecutar el Liberador de espacio en disco para liberar espacio del sistema", "Desactivar el inicio rápido en Opciones de energía"], "Las BSOD aleatorias con códigos de detención variables junto con errores en la prueba de memoria apuntan a RAM defectuosa. Reinstalar el driver de gráficos es tentador porque los drivers suelen causar BSOD, pero una falla de driver suele dar un código de detención constante y no haría fallar una prueba de memoria.", [null, "Una falla de driver suele dar un código de detención constante y no haría fallar una prueba de memoria.", "El poco espacio en disco no causa BSOD aleatorias con errores en la prueba de memoria.", "El inicio rápido afecta el apagado y el arranque, no los errores de memoria que muestra el diagnóstico."]],
  "x49": ["Un contrato establece que el proveedor de servicios administrados debe responder a los tickets críticos en una hora y restablecer el servicio en cuatro horas. ¿Qué documento es este?", ["Política de uso aceptable", "Acuerdo de nivel de servicio", "Procedimiento operativo estándar", "Artículo de la base de conocimientos"], "Un acuerdo de nivel de servicio (SLA) define compromisos de servicio medibles, como los tiempos de respuesta y resolución. Un SOP es tentador porque también guía el trabajo de soporte, pero describe cómo realizar una tarea, no los compromisos contractuales del proveedor.", ["Una AUP indica a los usuarios qué pueden y qué no pueden hacer con los sistemas de la empresa.", null, "Un SOP da instrucciones paso a paso para tareas, no tiempos de respuesta contractuales.", "Un artículo de la base de conocimientos documenta cómo resolver problemas, no compromisos de servicio."]],
  "x50": ["Un técnico de nivel 1 siguió los pasos de la base de conocimientos, pero no puede resolver una caída del servidor de archivos que afecta a todo el departamento de ventas. ¿Qué debe hacer?", ["Cerrar el ticket y decir a los usuarios que reinicien", "Seguir trabajando solo sin actualizar el ticket", "Aumentar la severidad y escalar con notas claras", "Abrir un ticket separado para cada usuario afectado"], "Una caída que afecta a todo un departamento es de alta severidad, y cuando fallan los pasos de primer nivel debe escalarse con notas para que el siguiente nivel no repita el trabajo. Abrir un ticket por usuario es tentador, pero divide un solo incidente y oculta su impacto real.", ["Cerrar el ticket de una caída sin resolver oculta un problema grave y deja a los usuarios sin servicio.", "Trabajar en silencio desperdicia tiempo en una caída de alto impacto y no deja registro para los demás.", null, "Los tickets separados dividen un solo incidente y ocultan su verdadero alcance."]],
  "x51": ["Un servidor recibe un respaldo completo el domingo y respaldos incrementales las demás noches. Falla el jueves por la mañana. ¿Qué respaldos se necesitan para la restauración?", ["Solo el respaldo incremental más reciente", "El completo del domingo más el incremental del miércoles", "Solo el respaldo completo del domingo", "El completo del domingo más los incrementales de lunes a miércoles"], "Cada incremental contiene solo los cambios desde el respaldo anterior, así que hay que restaurar en orden el completo más cada incremental posterior. El completo más solo el miércoles es tentador porque así funcionan los diferenciales, pero se perderían los cambios del lunes y el martes.", ["El incremental más reciente solo contiene los cambios del miércoles, no el conjunto completo de datos.", "Omitir los incrementales del lunes y el martes perdería los cambios de esos días.", "El completo por sí solo perdería todo lo cambiado de lunes a miércoles.", null]],
  "x52": ["Un servidor de sucursal tiene un enlace WAN lento. La empresa quiere un respaldo completo semanal sin copiar todo el conjunto de datos por el enlace, así que el servidor de respaldo construye el completo a partir del último completo y los incrementales. ¿Cómo se llama esto?", ["Respaldo completo sintético", "Respaldo diferencial", "Respaldo incremental", "Rotación abuelo-padre-hijo (GFS)"], "Un completo sintético se arma del lado del respaldo a partir de un completo anterior más los incrementales posteriores, sin volver a leer todos los datos del origen. El diferencial es tentador, pero solo contiene los cambios desde el último completo, no es un nuevo respaldo completo.", [null, "Un diferencial contiene los cambios desde el último completo; no es un nuevo respaldo completo.", "Un incremental contiene los cambios desde el último respaldo, no un completo.", "GFS es un esquema de rotación de medios, no una forma de construir un respaldo completo."]],
  "x53": ["Antes de desplegar una nueva versión de la aplicación contable para todos, el comité asesor de cambios quiere pruebas de que funciona con los datos y complementos de la empresa sin poner en riesgo producción. ¿Qué debe hacer el solicitante?", ["Desplegarla a todos los usuarios un viernes por la noche", "Probarla en un sandbox que replique producción", "Escribir el plan de reversión después del despliegue", "Omitir las pruebas porque el fabricante ya la probó"], "Probar en un sandbox que es copia de producción muestra cómo se comporta el cambio sin poner en riesgo los sistemas en vivo. Confiar en las pruebas del fabricante es tentador, pero el fabricante no la probó con los datos y complementos de esta empresa.", ["Desplegar a todos sin probar arriesga una caída en toda la empresa.", null, "El plan de reversión debe escribirse antes del cambio, no después.", "El fabricante no la probó con los datos y complementos de esta empresa."]],
  "x54": ["Se inicia un pequeño incendio eléctrico dentro de un UPS en el cuarto de servidores. ¿Qué extintor es el apropiado?", ["Un extintor de agua presurizada", "Un extintor de espuma Clase A", "Un extintor de CO2 (Clase C)", "Una toalla mojada arrojada sobre el UPS"], "Los incendios eléctricos necesitan un agente no conductor como el CO2, clasificado para incendios eléctricos Clase C en el sistema de EE. UU. La espuma es tentadora porque sofoca el fuego, pero la espuma a base de agua conduce electricidad y no está clasificada para equipos eléctricos energizados.", ["El agua conduce electricidad y no es segura en equipos eléctricos energizados.", "La espuma a base de agua es para combustibles comunes y puede conducir electricidad.", null, "Una toalla mojada agrega agua conductora y no apaga de forma confiable un incendio eléctrico."]],
  "x55": ["Un técnico recolecta varias baterías de iones de litio hinchadas de laptops durante una renovación de equipos. ¿Cómo deben desecharse?", ["Ponerlas en la basura normal dentro de una bolsa sellada", "Perforarlas primero para liberar la presión", "Guardarlas en un armario de suministros cálido hasta que las recojan", "Reciclarlas según las normas locales de residuos peligrosos"], "Las baterías de iones de litio deben ir a un reciclador aprobado o a un programa de residuos peligrosos según la normativa local. Sellarlas en la basura normal es tentador porque parece contenido, pero pueden incendiarse y generalmente están prohibidas en los residuos comunes.", ["Las baterías de iones de litio pueden incendiarse y generalmente no se permiten en la basura normal.", "Perforar una batería de iones de litio puede causar un incendio o una explosión.", "El calor aumenta el riesgo de que una batería dañada se incendie.", null]],
  "x56": ["Una laptop que podría contener evidencia de fraude pasa del técnico al equipo de seguridad y luego a las autoridades. ¿Qué documenta cada entrega del dispositivo?", ["Cadena de custodia", "Formulario de solicitud de cambio", "Registro de etiqueta de activo", "Certificado de destrucción"], "La cadena de custodia registra quién tuvo la evidencia, cuándo y por qué, para que siga siendo admisible. El registro de etiqueta de activo es tentador porque rastrea dispositivos, pero registra la propiedad y la asignación, no el manejo de evidencia.", [null, "Una solicitud de cambio cubre cambios planificados de TI, no el manejo de evidencia.", "Un registro de etiqueta de activo rastrea la propiedad y la asignación, no quién manejó la evidencia.", "Un certificado de destrucción prueba el desecho, lo contrario de preservar evidencia."]],
  "x57": ["Una tienda en línea con sede en EE. UU. empieza a vender a clientes de Francia y Alemania y almacena sus nombres y domicilios. ¿Qué regulación rige MÁS directamente estos datos personales?", ["PCI DSS", "GDPR", "HIPAA", "DRM"], "El GDPR protege los datos personales de las personas en la UE, sin importar dónde tenga su sede la empresa. PCI DSS es tentador porque la tienda recibe pagos, pero cubre los datos del titular de la tarjeta, no los nombres y domicilios en general.", ["PCI DSS cubre los datos de tarjetas de pago, no los nombres y domicilios en general.", null, "HIPAA cubre la información de salud en EE. UU., no los datos de clientes minoristas.", "DRM es protección contra copia de contenido digital, no una regulación de privacidad."]],
  "x58": ["En una llamada de soporte, un técnico le dice a un usuario no técnico que 'la resolución DNS falla por una caché del resolver obsoleta'. El usuario suena confundido. ¿Qué debe hacer el técnico?", ["Repetir la misma explicación más despacio", "Decirle al usuario que los detalles son demasiado técnicos para explicarlos", "Explicarlo en términos sencillos y confirmar que lo entendió", "Transferir la llamada a un técnico sénior"], "La buena comunicación implica evitar la jerga, usar lenguaje sencillo y verificar la comprensión. Repetirlo despacio es tentador, pero el problema es la jerga, no la velocidad.", ["Hablar despacio no ayuda cuando el problema es la propia jerga.", "Negarse a explicar no es profesional y deja al usuario sin información.", null, "El técnico puede resolver esto comunicándose mejor; escalar es innecesario."]],
  "x59": ["Un servidor Linux que solo tiene sus herramientas predeterminadas necesita un script que comprima los archivos de registro antiguos, ejecutado cada noche por cron. ¿Qué tipo de script es el MÁS adecuado?", ["Un archivo por lotes .bat", "Un archivo VBScript .vbs", "Un script de PowerShell .ps1", "Un script de shell .sh"], "Los scripts de shell (.sh) se ejecutan de forma nativa en Linux y son la forma estándar de automatizar tareas con cron. PowerShell es tentador porque puede ejecutarse en Linux, pero no viene instalado de forma predeterminada, mientras que el shell sí.", ["Los archivos por lotes se ejecutan en Windows, no en un servidor Linux.", "VBScript es un lenguaje de scripts de Windows que no se ejecuta de forma nativa en Linux.", "PowerShell puede ejecutarse en Linux, pero no viene instalado de forma predeterminada.", null]],
  "x60": ["El personal necesita acceder a sus PC Windows de la oficina desde casa usando Remote Desktop. ¿Qué enfoque es el MÁS seguro?", ["Exigir una VPN con MFA y mantener RDP fuera de internet", "Hacer port forwarding de TCP 3389 en el router hacia cada PC de la oficina", "Mover RDP a un puerto no estándar y reenviarlo", "Permitir RDP solo durante el horario laboral normal"], "Mantener RDP detrás de una VPN protegida con MFA impide que los atacantes lleguen a él directamente desde internet. Un puerto no estándar es tentador, pero los escáneres lo encuentran rápidamente y el servicio sigue expuesto a ataques de contraseñas.", [null, "Reenviar el 3389 expone RDP directamente a ataques de contraseñas y exploits desde internet.", "Un puerto no estándar es encontrado rápidamente por los escáneres y RDP sigue expuesto.", "Limitar el horario sigue dejando RDP expuesto a internet durante esas horas."]],
});
